Object.assign(window.TEM8_DICTIONARY, {"nobody":{"media":{"uk":"media/uk/nobody__gb_1.mp3","us":"media/us/nobody__us_1.mp3"},"oxford":{"phon":"ˈnəʊbədi","pos":"pronoun","senses":[{"en":"not anyone; no person","cn":"没有人；没有任何人","ex":{"en":"Nobody knew what to say.","cn":"谁也不知道该说什么。"}},{"en":"a person who has no importance or influence","cn":"小人物；无足轻重的人","ex":{"en":"She rose from being a nobody to being a superstar.","cn":"她从无名小辈一跃成为超级明星。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"PRON-INDEF-NEG 否定不定代词","cn":"没有人;无人","en":"Nobody means not a single person, or not a single member of a particular group or set.","ex":{"en":"They were shut away in a little room where nobody could overhear","cn":"他们被关在一个小屋里，没人能听到他们的动静。"}},{"pos":"N-COUNT 可数名词","cn":"无名之辈;小人物","en":"If someone says that a person is a nobody, they are saying in an unkind way that the person is not at all important.","ex":{"en":"A man in my position has nothing to fear from a nobody like you.","cn":"处在我这样位置的人，一点都不害怕像你这种小人物。"}}]},"examples":[{"en":"She rose from being a nobody to become a superstar.","cn":"她从无名小辈一跃成为超级明星。"},{"en":"Nobody knew what to say.","cn":"谁也不知道该说什么。"}]},"notoriously":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"famous because of doing something bad","cn":""},{"en":"famous because of doing something very bad, which seems immoral or evil","cn":""}]},"examples":[{"en":"notorious cases of human rights abuses","cn":"","src":"ld"},{"en":"a judge notorious for his cruelty and corruption","cn":"","src":"ld"}],"media":{"uk":"media/uk/notoriously__gb_1.mp3","us":"media/us/notoriously__us_1.mp3"},"oxford":{"phon":"nəʊˈtɔːriəsli","pos":"adverb","senses":[{"en":"in a way that is well known for being bad","cn":"声名狼藉的；臭名昭著的","ex":{"en":"Mountain weather is notoriously difficult to predict.","cn":"众所周知，山区天气很难预测。"}}]}},"no-nonsense":{"oxford":{"phon":"ˌnəʊ ˈnɒnsns","pos":"adjective","senses":[{"en":"simple and direct; only paying attention to important and necessary things","cn":"简单直接的；言简意赅的；不说废话的","ex":{"en":"a no-nonsense approach/style","cn":"严肃的方法/风格"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讲究实际的;直截了当的;不容胡闹的","en":"If you describe someone as a no-nonsense person, you approve of the fact that they are efficient, direct, and quite tough.","ex":{"en":"She saw herself as a direct, no-nonsense modern woman.","cn":"她认为自己是个直截了当、不拖泥带水的现代女性。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简单实用的","en":"If you describe something as a no-nonsense thing, you approve of the fact that it is plain and does not have unnecessary parts.","ex":{"en":"You'll need no-nonsense boots for the jungle.","cn":"你需要一双实用的靴子穿越丛林。"}}]},"media":{"uk":"media/uk/no_nonsense_1_gb_1.mp3","us":"media/us/no_nonsense_1_us_1.mp3"},"examples":[{"en":"his no-nonsense attitude to business","cn":"他在业务上的务实态度"}]},"noted":{"media":{"uk":"media/uk/noted__gb_1.mp3","us":"media/us/noted__us_1.mp3"},"oxford":{"phon":"ˈnəʊtɪd","pos":"adjective","senses":[{"en":"well known because of a special skill or feature","cn":"（以…）见称，闻名，著名","ex":{"en":"a noted dancer","cn":"著名的舞蹈演员"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"著名的;知名的","en":"To be noted for something you do or have means to be well-known and admired for it.","ex":{"en":"...a television programme noted for its attacks on organised crime","cn":"以抨击有组织犯罪而知名的电视节目"}}]},"examples":[{"en":"The lake is noted as a home to many birds.","cn":"这个湖作为许多鸟类的栖息地遐迩闻名。"},{"en":"He is not noted for his sense of humour.","cn":"他没什么幽默感。"}],"base":"not"},"novel":{"media":{"uk":"media/uk/novel__gb_1.mp3","us":"media/us/novel__us_1.mp3"},"oxford":{"phon":"ˈnɒvl","pos":"noun","senses":[{"en":"a story long enough to fill a complete book, in which the characters and events are usually imaginary","cn":"（长篇）小说","g":"[countable]","lab":"US English","ex":{"en":"to write/publish/read a novel","cn":"创作／出版／阅读小说"}},{"en":"the type of literature that novels represent","cn":"小说（文学）","g":"[singular]","ex":{"en":"The novel is the most adaptable of all literary forms.","cn":"小说是所有文学体裁中最适合改编的。"}},{"en":"different from anything known before; new, interesting and often seeming slightly strange","cn":"新颖的；与众不同的；珍奇的","ex":{"en":"a novel feature","cn":"新特征"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(长篇)小说","en":"A novel is a long written story about imaginary people and events.","ex":{"en":"...a novel by Herman Hesse","cn":"一部赫尔曼·黑塞的小说"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"新的;新奇的;新颖的","en":"Novel things are new and different from anything that has been done, experienced, or made before.","ex":{"en":"Protesters found a novel way of demonstrating against steeply rising oil prices","cn":"抗议者找到了抗议油价飞涨的新办法。"}}]},"examples":[{"en":"to write/publish/read a novel","cn":"创作/发表/阅读长篇小说"},{"en":"detective/historical/romantic novels","cn":"侦探/历史/言情小说"}]},"novice":{"media":{"uk":"media/uk/novice__gb_1.mp3","us":"media/us/novice__us_1.mp3"},"oxford":{"phon":"ˈnɒvɪs","pos":"noun","senses":[{"en":"a person who is new and has little experience in a skill, job or situation","cn":"新手；初学者","ex":{"en":"I'm a complete novice at skiing.","cn":"滑雪我完全是个新手。"}},{"en":"a person who has joined a religious group and is preparing to become a monk or a nun","cn":"初学修士（或修女）；（修会等的）初学生"},{"en":"a horse that has not yet won an important race","cn":"尚未赢过大赛的赛马"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"新手;生手;初学者","en":"A novice is someone who has been doing a job or other activity for only a short time and so is not experienced at it.","ex":{"en":"I'm a novice at these things, Lieutenant. You're the professional","cn":"中尉，做这些事情我是新手，你是行家。"}},{"pos":"N-COUNT 可数名词","cn":"见习修士(或修女)","en":"In a monastery or convent, a novice is a person who is preparing to become a monk or nun."}]},"examples":[{"en":"computer software for novices/the novice user","cn":"给初学者设计的电脑软件"},{"en":"I'm a complete novice at skiing.","cn":"滑雪我完全是个新手。"}]},"non-controversial":{"oxford":{"phon":"ˌnɒn kɒntrəˈvɜːʃl","pos":"adjective","senses":[{"en":"not causing, or not likely to cause, people to disagree","cn":"没有争议的；不会引起争议的"}]},"media":{"uk":"media/uk/non_controversial_1_gb_1.mp3","us":"media/us/non_controversial_1_us_1.mp3"},"examples":[{"en":"Most of the proposals are fairly non-controversial.","cn":"大多数提议都不会引起任何争议。"}]},"node":{"oxford":{"phon":"nəʊd","pos":"noun","senses":[{"en":"a place on the stem of a plant from which a branch or leaf grows","cn":"茎节","lab":"biology"},{"en":"a small swelling (= an area that is larger and rounder than normal) on a root or branch","cn":"（根或枝上的）节","lab":"biology"},{"en":"a point at which two lines or systems meet or cross","cn":"结点；节点","ex":{"en":"a network node","cn":"网络节点"}},{"en":"a piece of equipment such as a computer, that is attached to a network","cn":"连接到网络的设备（如计算机）","lab":"computing"},{"en":"a small hard mass of tissue, especially near a joint in the human body","cn":"（尤指人体关节附近的）硬结","lab":"anatomy","ex":{"en":"a lymph node","cn":"淋巴结"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"节;结;瘤","en":"A node is a point, especially in the form of lump or swelling, where one thing joins another.","ex":{"en":"Cut them off cleanly through the stem just below the node.","cn":"就从茎节下面，沿茎干把它们全砍掉。"}}]},"media":{"uk":"media/uk/node__gb_1.mp3","us":"media/us/node__us_1.mp3"},"examples":[{"en":"a network node","cn":"网络节点"},{"en":"a lymph node","cn":"淋巴结"}]},"noisily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making a lot of noise – used about sounds, voices, or music","cn":""},{"en":"making a lot of noise – used about people, machines, and places that are too loud","cn":""}]},"examples":[{"en":"The kids have been really noisy today.","cn":"","src":"ld"},{"en":"The bar was very noisy.","cn":"","src":"ld"}],"media":{"uk":"media/uk/noisily__gb_1.mp3","us":"media/us/noisily__us_1.mp3"},"oxford":{"phon":"ˈnɔɪzɪli","pos":"adverb","senses":[{"en":"in a way that makes a lot of noise","cn":"吵闹地；聒噪地；嘈杂地","ex":{"en":"The children were playing noisily upstairs.","cn":"孩子们在楼上吵闹地玩耍。"}}]}},"noon":{"media":{"uk":"media/uk/noon__gb_1.mp3","us":"media/us/noon__us_1.mp3"},"oxford":{"phon":"nuːn","pos":"noun","senses":[{"en":"12 o’clock in the middle of the day","cn":"正午；中午","ex":{"en":"We should be there by noon.","cn":"我们应该最晚中午到达。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"正午;中午","en":"Noon is twelve o'clock in the middle of the day.","ex":{"en":"The long day of meetings started at noon","cn":"会议接连不断的漫长一天从中午开始。"}},{"pos":"ADJ 形容词","cn":"正午的;中午的","en":"Noon means happening or appearing in the middle part of the day.","ex":{"en":"The noon sun was fierce","cn":"正午的阳光火辣辣的。"}},{"pos":"","cn":"","en":"morning, noon, and night→see: ;"}]},"examples":[{"en":"The conference opens at 12 noon on Saturday.","cn":"这次会议在星期六中午 12 点开幕。"},{"en":"the noon deadline for the end of hostilities","cn":"中午结束敌对状态这一最后期限"}]},"nonetheless":{"media":{"uk":"media/uk/nonetheless__gb_1.mp3","us":"media/us/nonetheless__us_1.mp3"},"oxford":{"phon":"ˌnʌnðəˈles","pos":"adverb","senses":[{"en":"despite this fact","cn":"尽管如此","ex":{"en":"The book is too long but, nonetheless, informative and entertaining.","cn":"这本书篇幅太长，但是很有知识性和趣味性。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"同 nevertheless","en":"Nonetheless means the same as nevertheless .","ex":{"en":"There was still a long way to go. Nonetheless, some progress had been made","cn":"路还很长，不过已经取得了一些进展。"}}]},"examples":[{"en":"The problems are not serious. Nonetheless, we shall need to tackle them soon.","cn":"问题不严重。不过我们还是需要尽快处理。"},{"en":"The book is too long but, nonetheless, informative and entertaining.","cn":"这本书太长，但是很有知识性和趣味性。"}]},"november":{"media":{"uk":"media/uk/november__gb_1.mp3","us":"media/us/november__us_1.mp3"},"oxford":{"phon":"nəʊˈvembə(r)","pos":"noun","senses":[{"en":"the 11th month of the year, between October and December","cn":"十一月","lab":"British English","ex":{"en":"She was born in November.","cn":"她出生于十一月。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"十一月","en":"November is the eleventh month of the year in the Western calendar.","ex":{"en":"He arrived in London in November 1939","cn":"他于1939年11月抵达伦敦。"}}]}},"nonsense":{"media":{"uk":"media/uk/nonsense__gb_1.mp3","us":"media/us/nonsense__us_1.mp3"},"oxford":{"phon":"ˈnɒnsns","pos":"noun","senses":[{"en":"ideas, statements or beliefs that you think are silly or not true","cn":"谬论；胡扯；胡言乱语","g":"[uncountable, countable]","ex":{"en":"Reports that he has resigned are nonsense.","cn":"有关他已经辞职的报道是无稽之谈。"}},{"en":"spoken or written words that have no meaning or make no sense","cn":"毫无意义的话；没有意义的文章","g":"[uncountable]","ex":{"en":"a book of children’s nonsense poems","cn":"一本儿童胡话诗集"}},{"en":"silly or unacceptable behaviour","cn":"愚蠢的行为；冒失；不可接受的行为","g":"[uncountable]","ex":{"en":"The new teacher won't stand for any nonsense.","cn":"这位新教师不会容忍任何无礼行为。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"胡说;假话;愚蠢的话","en":"If you say that something spoken or written is nonsense, you mean that you consider it to be untrue or silly.","ex":{"en":"Most orthodox doctors however dismiss this as complete nonsense.","cn":"但大多数传统的医生认为此说法完全是胡说八道。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"愚蠢的举动;冒失(或轻浮)的行为","en":"You can use nonsense to refer to something that you think is foolish or that you disapprove of.","ex":{"en":"Surely it is an economic nonsense to deplete the world of natural resources","cn":"耗尽世界的自然资源毋庸置疑是愚蠢的经济行为。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"无意义的话;荒谬的话","en":"You can refer to spoken or written words that do not mean anything because they do not make sense as nonsense .","ex":{"en":"...a children's nonsense poem by Charles E Carryl.","cn":"查尔斯·E.卡里尔写的一首儿童打油诗"}},{"pos":"PHRASE 短语","cn":"使变得荒唐;使失去意义","en":"To make a nonsense of something or to make nonsense of it means to make it seem ridiculous or pointless.","ex":{"en":"The fighting made a nonsense of peace pledges made in London last week","cn":"这场战斗使上周在伦敦所作的和平承诺变成一纸空文。"}}]},"examples":[{"en":"If people can bribe police officers, it makes a complete nonsense of the legal system.","cn":"如果人们可以收买警察，法律体系就会变得一文不值。"},{"en":"‘I won't go.’ ‘Nonsense! You must go!’ “","cn":"我不想去。” “胡扯！你一定得去！”"}]},"nodded":{"lemma":"nod"},"nowhere":{"media":{"uk":"media/uk/nowhere__gb_1.mp3","us":"media/us/nowhere__us_1.mp3"},"oxford":{"phon":"ˈnəʊweə(r)","pos":"adverb","senses":[{"en":"not in or to any place","cn":"无处；哪里都不","ex":{"en":"I had nowhere to live, so I was sleeping on my sister's couch.","cn":"我没有地方住，所以睡在姐姐的沙发上。"}}]},"collins":{"senses":[{"pos":"ADV-INDEF-NEG 否定不定副词","cn":"任何地方都不;没有别的地方会","en":"You use nowhere to emphasize that a place has more of a particular quality than any other places, or that it is the only place where something happens or exists.","ex":{"en":"Nowhere is language a more serious issue than in Hawaii","cn":"没有哪个地方像夏威夷那样，语言成了如此重要的问题。"}},{"pos":"ADV-INDEF-NEG 否定不定副词","cn":"没有任何地方;无处","en":"You use nowhere when making negative statements to say that a suitable place of the specified kind does not exist.","ex":{"en":"There was nowhere to hide and nowhere to run","cn":"无处可藏，也无处可逃。"}},{"pos":"ADV 副词","cn":"没有踪影;找不到","en":"You use nowhere to indicate that something or someone cannot be seen or found.","ex":{"en":"Michael glanced anxiously down the corridor, but Wilfred was nowhere to be seen","cn":"迈克尔焦急地顺着走廊望去，可根本看不到威尔弗雷德的影儿。"}},{"pos":"ADV 副词","cn":"在不重要的地方;在无趣之处","en":"You can use nowhere to refer in a general way to small, unimportant, or uninteresting places.","ex":{"en":"...endless paths that led nowhere in particular.","cn":"不知通往何处的没有尽头的小路"}},{"pos":"ADV 副词","cn":"突然(发生);一下子(冒出来)","en":"If you say that something or someone appears from nowhere or out of nowhere, you mean that they appear suddenly and unexpectedly.","ex":{"en":"A car came from nowhere, and I had to jump back into the hedge just in time","cn":"一辆轿车不知从什么地方突然冒了出来，我只得向后跳到树篱中躲避，险些躲不及。"}},{"pos":"ADV 副词","cn":"(文字、言谈或争论中)找不到出处地","en":"You use nowhere to mean not in any part of a text, speech, or argument.","ex":{"en":"He nowhere offers concrete historical background to support his arguments","cn":"他没给出具体的历史背景来支撑他的论点。"}},{"pos":"PHRASE 短语","cn":"在遥远偏僻处","en":"If you say that a place is in the middle of nowhere, you mean that it is a long way from other places.","ex":{"en":"At dusk we pitched camp in the middle of nowhere.","cn":"黄昏时，我们在茫茫荒野中扎营。"}},{"pos":"PHRASE 短语","cn":"(使)毫无结果;(使)一无进展","en":"If you say that you are getting nowhere, or getting nowhere fast, or that something is getting you nowhere, you mean that you are not achieving anything or having any success.","ex":{"en":"My mind won't stop going round and round on the same subject and I seem to be getting nowhere","cn":"我脑子一直在不停地围绕着同一个问题转啊转，但一无所获。"}},{"pos":"PHRASE 短语","cn":"远非;远不及","en":"If you use nowhere near in front of a word or expression, you are emphasizing that the real situation is very different from, or has not yet reached, the state which that word or expression suggests.","ex":{"en":"He's nowhere near recovered yet from his experiences","cn":"他还远没有从自己的经历中走出来。"}}]},"examples":[{"en":"‘Where are you going this weekend?’ ‘Nowhere special.’ “","cn":"这个周末你打算去哪儿？” “没什么地方可去。”"},{"en":"We discussed it all morning but got nowhere.","cn":"我们就此事讨论了一上午，可是毫无进展。"}]},"noble":{"media":{"uk":"media/uk/noble__gb_1.mp3","us":"media/us/noble__us_1.mp3"},"oxford":{"phon":"ˈnəʊbl","pos":"adjective","senses":[{"en":"having or showing fine personal qualities that people admire, such as courage, honesty and care for others","cn":"崇高的；品质高尚的","ex":{"en":"a noble leader","cn":"伟大的领袖"}},{"en":"belonging to a family of high social rank (= belonging to the nobility)","cn":"贵族的；高贵的","ex":{"en":"He was a young man of noble birth.","cn":"他是个出身高贵的年轻人。"}},{"en":"very impressive in size or quality","cn":"宏伟的；壮丽的","ex":{"en":"a noble building","cn":"雄伟的大楼"}},{"en":"a person who comes from a family of high social rank; a member of the nobility","cn":"出身高贵的人；贵族成员","ex":{"en":"The cost of the arch was met by Milanese nobles.","cn":"拱门的费用由米兰贵族承担。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)高尚的，崇高的","en":"If you say that someone is a noble person, you admire and respect them because they are unselfish and morally good.","ex":{"en":"He was an upright and noble man who was always willing to help in any way he could","cn":"他是一个正直高尚的人，总是愿意尽其所能帮助他人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(想法、目标、行动等)高尚的,崇高的","en":"If you say that something is a noble idea, goal, or action, you admire it because it is based on high moral principles.","ex":{"en":"He had implicit faith in the noble intentions of the Emperor","cn":"他对皇帝陛下高尚的动机深信不疑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"壮观的;宏伟的;卓越的;优质的","en":"If you describe something as noble, you think that its appearance or quality is very impressive, making it superior to other things of its type.","ex":{"en":"...the great parks with their noble trees.","cn":"树木参天的大公园"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贵族的","en":"Noble means belonging to a high social class and having a title.","ex":{"en":"...rich and noble families","cn":"侯门朱户"}},{"pos":"N-COUNT 可数名词","cn":"(旧时的)贵族","en":"In former times, people who belonged to a high social class and had titles such as 'Baron' or 'Duke' were referred to as nobles .","ex":{"en":"More and more nobles made Moscow their home during Catherine's reign.","cn":"在叶卡捷琳娜大帝统治时期，越来越多的贵族移居莫斯科。"}}]},"examples":[{"en":"She bore the disappointment nobly.","cn":"她很失望，但表现得很大度。"},{"en":"He died for a noble cause.","cn":"他为了高尚的事业而牺牲。"}]},"notebook":{"media":{"img":["media/ldoce/img/notebook.jpg","media/pic/stationery_supplies_comp.jpg"],"uk":"media/uk/notebook__gb_1.mp3","us":"media/us/notebook__us_1.mp3"},"oxford":{"phon":"ˈnəʊtbʊk","pos":"noun","senses":[{"en":"a small book of plain paper for writing notes in","cn":"笔记本","ex":{"en":"The police officer wrote the details down in his notebook.","cn":"警察把详细情况记在笔记本上。"}},{"en":"a small book for students to write their work in","cn":"练习本","lab":"North American English"},{"en":"a small computer that can work with a battery and be easily carried","cn":"笔记本计算机；笔记本电脑"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"笔记本;笔记簿","en":"A notebook is a small book for writing notes in.","ex":{"en":"He brought out a notebook and pen from his pocket.","cn":"他从口袋里掏出笔记本和钢笔。"}},{"pos":"N-COUNT 可数名词","cn":"笔记本(电脑)","en":"A notebook computer is a small personal computer.","ex":{"en":"...a range of notebook computers which allows all your important information to travel safely with you.","cn":"使你能够随身携带所有重要信息安全旅行的各种笔记本电脑"}}]}},"non-profit":{"oxford":{"phon":"ˌnɒn ˈprɒfɪt","pos":"adjective","senses":[{"en":"without the aim of making a profit","cn":"非营利的","ex":{"en":"an independent non-profit organization","cn":"独立的非营利机构"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非营利的","en":"A non-profit organization is one which is not run with the aim of making a profit.","ex":{"en":"Her center is typical of many across the country — a non-profit organization that cares for about 50 children.","cn":"她的中心照顾着大约50名儿童，是全国众多非营利机构的典型代表。"}}]},"media":{"uk":"media/uk/non_profit_1_gb_1.mp3","us":"media/us/non_profit_1_us_1.mp3"},"examples":[{"en":"The centre is run on a non-profit basis.","cn":"这个中心的运作不以营利为目的。"},{"en":"The charity is non-profit-making.","cn":"这个慈善团体不以营利为目的。"}]},"nonchalant":{"media":{"uk":"media/uk/nonchalant__gb_1.mp3","us":"media/us/nonchalant__us_1.mp3"},"oxford":{"phon":"ˈnɒnʃələnt","pos":"adjective","senses":[{"en":"behaving in a calm and relaxed way; giving the impression that you are not feeling worried","cn":"若无其事的；冷静的；漠不关心的","ex":{"en":"to appear/look/sound nonchalant","cn":"显得／看上去／听起来满不在乎的样子"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无动于衷的;漠不关心的","en":"If you describe someone as nonchalant, you mean that they appear not to worry or care about things and that they seem very calm.","ex":{"en":"Clark's mother is nonchalant about her role in her son's latest work","cn":"克拉克的母亲对自己在儿子最新作品中的角色漠不关心。"}}]},"examples":[{"en":"‘It'll be fine,’ she replied, with a nonchalant shrug.","cn":"她若无其事地耸耸肩说：“会没事的。”"},{"en":"He was leaning nonchalantly against the wall.","cn":"他漫不经心地斜倚着墙。"}]},"non-human":{"oxford":{"phon":"ˌnɒn ˈhjuːmən","pos":"adjective","senses":[{"en":"not human","cn":"非人类的","ex":{"en":"similarities between human and non-human animals","cn":"人和其他动物之间的相似之处"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非人类的;不属于人类的","en":"Non-human means not human or not produced by humans.","ex":{"en":"Hostility towards outsiders is characteristic of both human and non-human animals.","cn":"对外来者怀有敌意是人类和其他动物共有的特征。"}}]},"media":{"uk":"media/uk/non_human_1_gb_1.mp3","us":"media/us/non_human_1_us_1.mp3"},"examples":[{"en":"similarities between human and non-human animals","cn":"人和其他动物之间的相似之处"}]},"nomadic":{"media":{"uk":"media/uk/nomadic__gb_1.mp3","us":"media/us/nomadic__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"游牧的;游牧部落的","en":"Nomadic people travel from place to place rather than living in one place all the time.","ex":{"en":"...the great nomadic tribes of the Western Sahara.","cn":"西撒哈拉伟大的游牧部落"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"流浪的","en":"If someone has a nomadic way of life, they travel from place to place and do not have a settled home.","ex":{"en":"The daughter of a railway engineer, she at first had a somewhat nomadic childhood.","cn":"作为一个铁路工程师的女儿，她最初的童年生活有些漂泊不定。"}}]},"examples":[{"en":"the nomadic life of a foreign correspondent","cn":"驻国外记者的流浪生活"},{"en":"nomadic tribes","cn":"游牧部落"}],"oxford":{"phon":"nəʊˈmædɪk","pos":"adjective","senses":[{"en":"belonging to a community that moves with its animals from place to place","cn":"游牧的","ex":{"en":"nomadic tribes","cn":"游牧部落"}},{"en":"moving often from place to place","cn":"流浪的，经常搬家的","ex":{"en":"the nomadic life of a foreign correspondent","cn":"外派记者漂泊不定的生活"}}]}},"nonverbal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不使用语言的;非言语的","en":"Non-verbal communication consists of things such as the expression on your face, your arm movements, or your tone of voice, which show how you feel about something without using words.","ex":{"en":"Culture plays a large part in non-verbal communication","cn":"文化在非语言交流中起着很大的作用。"}}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41nonverbal.mp3","us":"media/ldoce/hwd/ame/1/nonverbal.mp3"},"examples":[{"en":"nonverbal forms of communication","cn":"非语言交际形式"}]},"north":{"media":{"uk":"media/uk/north__gb_1.mp3","us":"media/us/north__us_1.mp3"},"oxford":{"phon":"nɔːθ","pos":"noun","senses":[{"en":"the direction that is on your left when you watch the sun rise; one of the four main points of the compass","cn":"北；北方","ex":{"en":"Which way is north?","cn":"哪边是北？"}},{"en":"the northern part of a country, a region or the world","cn":"北部；北部地区","ex":{"en":"birds migrating from the north","cn":"从北方迁徙来的鸟"}},{"en":"the north-east states of the US which fought against the South in the American Civil War","cn":"（美国南北战争时与南方作战的）北部各州，北方","ex":{"en":"Some delegates from Virginia voted to join the North.","cn":"来自弗吉尼亚州的一些代表投票支持加入北方。"}},{"en":"the richer and more developed countries of the world, especially in Europe and North America","cn":"北方发达国家（尤指欧洲和北美各国）","ex":{"en":"The North refused to commit itself to safeguarding species diversity.","cn":"北方拒绝承诺保护物种多样性。"}},{"en":"in or towards the north","cn":"北方的；向北的；北部的","ex":{"en":"North London","cn":"伦敦北区"},"pos":"adjective"},{"en":"a north wind blows from the north","cn":"北风的；北方吹来的","ex":{"en":"A cold north wind blew in from the sea.","cn":"一股寒冷的北风从海上吹来。"},"pos":"adjective"},{"en":"towards the north","cn":"向北；朝北","ex":{"en":"The house faces north.","cn":"这房子朝北。"},"pos":"adverb"},{"en":"nearer to the north than something","cn":"某物以北","ex":{"en":"They live ten miles north of Boston.","cn":"他们居住在波士顿以北 10 英里处。"},"pos":"adverb"},{"en":"more or higher than something","cn":"超过","lab":"finance or North American English, informal，，","ex":{"en":"The estimated value is north of $5.4 billion.","cn":"估价高于 54 亿美元。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"北;北方","en":"The north is the direction which is on your left when you are looking towards the direction where the sun rises.","ex":{"en":"In the north the ground becomes very cold as the winter snow and ice covers the ground","cn":"冬天冰雪覆盖大地，北方的地面变得非常寒冷。"}},{"pos":"N-SING 单数名词","cn":"北部;北部地区","en":"The north of a place, country, or region is the part which is in the north.","ex":{"en":"The scheme mostly benefits people in the North and Midlands.","cn":"该方案主要的受益者是北部和中部地区的人们。"}},{"pos":"ADV 副词","cn":"向北方","en":"If you go north, you travel towards the north.","ex":{"en":"Anita drove north up Pacific Highway.","cn":"安妮塔驱车沿太平洋公路向北行驶。"}},{"pos":"ADV 副词","cn":"在北方","en":"Something that is north of a place is positioned to the north of it.","ex":{"en":"...a little village a few miles north of Portsmouth.","cn":"位于朴次茅斯以北几英里处的小村庄"}},{"pos":"ADJ 形容词","cn":"在北方的;北部的;向北方的;面朝北的","en":"The north edge, corner, or part of a place or country is the part which is towards the north.","ex":{"en":"...the north side of the mountain","cn":"山的北面"}},{"pos":"ADJ 形容词","cn":"(用在国家、州和地区名中)北(的)","en":"'North' is used in the names of some countries, states, and regions in the north of a larger area.","ex":{"en":"There were demonstrations this weekend in cities throughout North America, Asia and Europe.","cn":"本周末在北美、亚洲和欧洲的多个城市举行了示威游行。"}},{"pos":"ADJ 形容词","cn":"(风)从北方吹来的","en":"A north wind is a wind that blows from the north.","ex":{"en":"...a bitterly cold north wind.","cn":"凛冽的北风"}},{"pos":"N-SING 单数名词","cn":"北方发达国家(指大部分位于北半球的富裕、发达国家)","en":"The North is used to refer to the richer, more developed countries of the world.","ex":{"en":"Malaysia has emerged as the toughest critic of the North's environmental attitudes.","cn":"马来西亚已成为对北方发达国家环保态度最严厉的批评者。"}}]},"examples":[{"en":"They live ten miles north of Boston.","cn":"他们居住在波士顿以北 10 英里处。"},{"en":"They've gone to live up north.","cn":"他们已经搬到北方去住了。"}]},"noteworthy":{"oxford":{"phon":"ˈnəʊtwɜːði","pos":"adjective","senses":[{"en":"deserving to be noticed or to receive attention because it is unusual, important or interesting","cn":"值得注意的；显著的；重要的","ex":{"en":"a noteworthy feature","cn":"一个值得注意的特点"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"值得注意的;显著的;有趣的","en":"A fact or event that is noteworthy is interesting, remarkable, or significant in some way.","ex":{"en":"It is noteworthy that the programme has been shifted from its original August slot to July","cn":"值得注意的是该节目已从原来8月份的档期换到了7月份。"}}]},"media":{"uk":"media/uk/noteworthy__gb_1.mp3","us":"media/us/noteworthy__us_1.mp3"},"examples":[{"en":"a noteworthy achievement","cn":"显著的成就"}]},"nose":{"media":{"uk":"media/uk/nose__gb_1.mp3","us":"media/us/nose__us_1.mp3"},"oxford":{"phon":"nəʊz","pos":"noun","senses":[{"en":"the part of the face that sticks out above the mouth, used for breathing and smelling things","cn":"鼻；鼻子","g":"[countable]","lab":"figurative","ex":{"en":"She had dark eyes and a long narrow nose.","cn":"她长着黑色的眼睛和细长的鼻子。"}},{"en":"having the type of nose mentioned","cn":"有…鼻子的","ex":{"en":"red-nosed","cn":"红鼻子的"}},{"en":"the front part of a plane, spacecraft, etc.","cn":"（飞机、太空船等的）头部，头锥；机头","g":"[countable]","ex":{"en":"Heat detectors are fitted in the nose of the missile.","cn":"热探测器安装在导弹的前端。"}},{"en":"a special ability for finding or recognizing something","cn":"发现（或辨别）事物的能力；嗅觉","g":"[singular]","ex":{"en":"As a journalist, she has always had a nose for a good story.","cn":"作为一名记者，她总是能够捕捉到好新闻。"}},{"en":"a sense of smell","cn":"嗅觉","g":"[singular]","lab":"figurative","ex":{"en":"a dog with a good nose","cn":"嗅觉灵敏的狗"}},{"en":"a smell that is characteristic of a particular wine","cn":"（酒的）香气","g":"[singular]","ex":{"en":"This Cote de Beaune has a good nose, with apricot and raisin aromas.","cn":"这款 Cote de Beaune 酒的香气很好，带有杏子和葡萄干的香气。"}},{"en":"to move forward slowly and carefully","cn":"小心翼翼地向前移动","g":"[intransitive, transitive]","ex":{"en":"The plane nosed down through the thick clouds.","cn":"飞机穿过厚厚的云层慢慢向下降落。"},"pos":"verb"},{"en":"to search for something or push something with its nose","cn":"（用鼻子）嗅，拱，顶","g":"[intransitive]","ex":{"en":"Dogs nosed around in piles of refuse.","cn":"一群狗在垃圾堆上嗅来嗅去。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鼻子","en":"Your nose is the part of your face which sticks out above your mouth. You use it for smelling and breathing.","ex":{"en":"She wiped her nose with a tissue","cn":"她用纸巾擦了擦鼻子。"}},{"pos":"N-COUNT 可数名词","cn":"(汽车或飞机的)前部;车头;机头","en":"The nose of a vehicle such as a car or aeroplane is the front part of it.","ex":{"en":"Sue parked off the main street, with the van's nose pointing away from the street.","cn":"休把小货车停在远离大街的地方，车头背对着大街。"}},{"pos":"N-COUNT 可数名词","cn":"嗅觉","en":"You can refer to your sense of smell as your nose .","ex":{"en":"The river that runs through Middlesbrough became ugly on the eye and hard on the nose.","cn":"穿过米德尔斯伯勒的那条河变得污秽不堪、臭不可闻。"}},{"pos":"N-SING 单数名词","cn":"(赛马中)以一鼻之差","en":"If a horse wins a race by a nose, it wins by a very small distance.","ex":{"en":"Chirkpar rattled past him on the right to snatch the prize by a nose.","cn":"一匹名为切厄克帕的赛马从他右侧疾驰而过，以一鼻之差获胜。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)小心翼翼地缓慢行驶","en":"If a vehicle noses in a certain direction or if you nose it there, you move it slowly and carefully in that direction.","ex":{"en":"He could not see the driver as the car nosed forward","cn":"车慢慢向前开，他却看不见司机。"}},{"pos":"PHRASE 短语","cn":"行为规矩;不惹是非","en":"If you keep your nose clean, you behave well and stay out of trouble.","ex":{"en":"If you kept your nose clean, you had a job for life.","cn":"如果你规规矩矩，就可以一辈子都捧着这个饭碗。"}},{"pos":"PHRASE 短语","cn":"笔直往前;沿最明显路线","en":"If you follow your nose to get to a place, you go straight ahead or follow the most obvious route.","ex":{"en":"Just follow your nose and in about five minutes you're at the old railway.","cn":"径直往前开，大约5分钟就能到旧铁路线。"}},{"pos":"PHRASE 短语","cn":"凭直觉行事;凭本能行事","en":"If you follow your nose, you do something in a particular way because you feel it should be done like that, rather than because you are following any plan or rules.","ex":{"en":"You won't have to think, just follow your nose.","cn":"你不必思考，跟着你的直觉走。"}},{"pos":"PHRASE 短语","cn":"对…很敏感;很善于发现","en":"If you say that someone has a nose for something, you mean that they have a natural ability to find it or recognize it.","ex":{"en":"He had a nose for trouble and a brilliant tactical mind","cn":"他善于发现问题，还总能想出高明的策略。"}},{"pos":"PHRASE 短语","cn":"使生气;惹…发火","en":"If you say that someone or something gets up your nose, you mean that they annoy you.","ex":{"en":"He's just getting up my nose so much at the moment.","cn":"他这会儿真让我生气。"}},{"pos":"PHRASE 短语","cn":"瞧不起;不把…放在眼里","en":"If you say that someone looks down their nose at something or someone, you mean that they believe they are superior to that person or thing and treat them with disrespect.","ex":{"en":"I don't look down my nose at comedy","cn":"我并不轻视喜剧。"}},{"pos":"PHRASE 短语","cn":"付高价;付出过大代价","en":"If you say that you paid through the nose for something, you are emphasizing that you had to pay what you consider too high a price for it.","ex":{"en":"We don't like paying through the nose for our wine when eating out.","cn":"下馆子时，我们不喜欢在酒水上花很多钱。"}},{"pos":"PHRASE 短语","cn":"探问;探看;干预","en":"If someone pokes their nose into something or sticks their nose into something, they try to interfere with it even though it does not concern them.","ex":{"en":"We don't like strangers who poke their noses into our affairs","cn":"我们不喜欢陌生人干预我们的事务。"}},{"pos":"PHRASE 短语","cn":"反复向…提及(不愉快的事);揭…的疮疤","en":"To rub someone's nose in something that they do not want to think about, such as a failing or a mistake they have made, means to remind them repeatedly about it.","ex":{"en":"His enemies will attempt to rub his nose in past policy statements.","cn":"他的对手会试图揪住他过去政策陈述的漏洞不放。"}},{"pos":"PHRASE 短语","cn":"跟别人怄气却害了自己;赌气做出不顾后果的事","en":"If you say that someone is cutting off their nose to spite their face, you mean they do something that they think will hurt someone, without realizing or caring that it will hurt themselves as well.","ex":{"en":"There is evidence that the industry's greed means that it is cutting off its nose to spite its face.","cn":"有证据表明该产业的贪婪是在作茧自缚。"}},{"pos":"PHRASE 短语","cn":"(车辆)首尾相连","en":"If vehicles are nose to tail, the front of one vehicle is close behind the back of another.","ex":{"en":"...a line of about twenty fast-moving trucks driving nose to tail.","cn":"一排大约20辆首尾相接、快速行驶的卡车"}},{"pos":"PHRASE 短语","cn":"对…嗤之以鼻;蔑视","en":"If you thumb your nose at someone, you behave in a way that shows that you do not care what they think.","ex":{"en":"He has always thumbed his nose at the media.","cn":"他对媒体一直都嗤之以鼻。"}},{"pos":"PHRASE 短语","cn":"对…不屑一顾;嫌弃","en":"If you turn up your nose at something, you reject it because you think that it is not good enough for you.","ex":{"en":"I'm not in a financial position to turn up my nose at several hundred thousand pounds.","cn":"我的经济境况使我无法对几十万英镑无动于衷。"}},{"pos":"PHRASE 短语","cn":"当着…的面;在…的眼皮底下","en":"If you do something under someone's nose, you do it right in front of them, without trying to hide it from them.","ex":{"en":"Okay so have an affair, but not right under my nose.","cn":"有外遇就有外遇好了，但别在我眼皮底下。"}},{"pos":"","cn":"","en":"to put someone's nose out of joint→see: ;"},{"pos":"","cn":"","en":"相关词组：nose around"}]},"examples":[{"en":"The budget should hit the $136 billion target on the nose.","cn":"预算应该正好达到 1 360 亿元的目标。"},{"en":"The police didn't know the drugs ring was operating right under their noses.","cn":"警方不知道贩毒集团就在他们的眼皮底下运作。"}]},"normally":{"media":{"uk":"media/uk/normally__gb_1.mp3","us":"media/us/normally__us_1.mp3"},"oxford":{"phon":"ˈnɔːməli","pos":"adverb","senses":[{"en":"usually; in normal circumstances","cn":"通常；正常情况下","ex":{"en":"I would never normally discuss this.","cn":"我平常不会谈论这个。"}},{"en":"in the usual or ordinary way","cn":"正常地；平常地","ex":{"en":"Her heart is beating normally.","cn":"她心跳正常。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"正常地;通常;平常","en":"If you say that something normally happens or that you normally do a particular thing, you mean that it is what usually happens or what you usually do.","ex":{"en":"All airports in the country are working normally today","cn":"今天国内所有机场都运转正常。"}},{"pos":"ADV 副词","cn":"常规地;按惯例","en":"If you do something normally, you do it in the usual or conventional way.","ex":{"en":"She would apparently eat normally and then make herself sick.","cn":"她显然还会照吃不误，然后把自己吃到恶心。"}}]},"examples":[{"en":"I'm not normally allowed to stay out late.","cn":"通常情况下，我不能在外很晚不归。"},{"en":"It normally takes 20 minutes to get there.","cn":"去那儿一般要花 20 分钟。"}]},"no":{"media":{"uk":"media/uk/no__gb_1.mp3","us":"media/us/no__us_1.mp3"},"oxford":{"phon":"nəʊ","pos":"exclamation","senses":[{"en":"used to give a negative reply or statement","cn":"（用于否定的回答或陈述）不；没有；不是","ex":{"en":"Just say yes or no.","cn":"只要说“是”或“不是”。"}},{"en":"used to express shock or surprise at what somebody has said","cn":"（对某人所说的话感到惊讶）不，不要","ex":{"en":"‘She's had an accident.’ ‘Oh no!’","cn":"“她发生了意外。”“怎么会呢！”"}},{"en":"not one; not any; not a","cn":"没有；无","ex":{"en":"No student is to leave the room.","cn":"学生一律不许离开这房间。"},"pos":"determiner"},{"en":"used, for example on notices, to say that something is not allowed","cn":"不准；禁止","ex":{"en":"No smoking!","cn":"禁止吸烟！"},"pos":"determiner"},{"en":"used to express the opposite of what is mentioned","cn":"（表示情况的反面）不是，并不","ex":{"en":"She's no fool (= she's intelligent).","cn":"她并不傻。"},"pos":"determiner"},{"en":"used to say that it is impossible to do something","cn":"没有可能（做某事）","ex":{"en":"There's no telling what will happen next.","cn":"下一步还不定会发生什么事。"},"pos":"determiner"},{"en":"used before adjectives and adverbs to mean ‘not’","cn":"（与 not 同义，用于形容词和副词前）不","ex":{"en":"She's feeling no better this morning.","cn":"她今天早晨还是不见好转。"},"pos":"adverb"},{"en":"an answer that shows you do not agree with an idea, a statement, etc.; a person who says ‘no’","cn":"否定的回答；作否定回答的人","ex":{"en":"Can't you give me a straight yes or no?","cn":"“是”还是“否”，你就不能给我个直截了当的回答吗？"},"pos":"noun"},{"en":"the total number of people voting ‘no’ in a formal debate, for example in a parliament","cn":"（统称）投反对票者","g":"[plural]","ex":{"en":"The noes have it (= more people have voted against something than for it).","cn":"投反对票者占多数。"},"pos":"noun"},{"en":"number","cn":"数字","lab":"British English also","ex":{"en":"Room No. 145","cn":"145 号房间"},"pos":"abbreviation"},{"en":"north; northern","cn":"北方（的）；北部（的）","lab":"North American English","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"(用于否定回答)不，没有","en":"You use no to give a negative response to a question.","ex":{"en":"'Any problems?' — 'No, I'm O.K.'","cn":"“有问题吗？”——“没有，我挺好的。”"}},{"pos":"CONVENTION 惯用语","cn":"不对;不是","en":"You use no to say that something that someone has just said is not true.","ex":{"en":"'We thought you'd emigrated.' — 'No, no.'","cn":"“我们以为你移居国外了。”——“不，没有。”"}},{"pos":"CONVENTION 惯用语","cn":"(用于拒绝建议、请求或拒绝给予许可)不要，不行，不用","en":"You use no to refuse an offer or a request, or to refuse permission.","ex":{"en":"'Here, have mine.' — 'No, this is fine.'","cn":"“喏，用我的。”——“不用，这就挺好。”"}},{"pos":"EXCLAM 感叹语","cn":"(用于表示不想让某人做某事)不要，不可","en":"You use no to indicate that you do not want someone to do something.","ex":{"en":"No. I forbid it. You cannot","cn":"不，我不允许那样，你不能…"}},{"pos":"CONVENTION 惯用语","cn":"(表示接受或理解对方的否定说法)对的，是的","en":"You use no to acknowledge a negative statement or to show that you accept and understand it.","ex":{"en":"'We're not on the main campus.' — 'No.'","cn":"“我们不是在主校区。”——“是的，不在。”"}},{"pos":"CONVENTION 惯用语","cn":"(用于纠正刚说的话)噢不，啊不","en":"You use no before correcting what you have just said.","ex":{"en":"I was twenty-two — no, twenty-one.","cn":"我当时22岁，哎呀不对，是21岁。"}},{"pos":"EXCLAM 感叹语","cn":"(用于表示震惊或失望)不会吧，是吗，真的","en":"You use no to express shock or disappointment at something you have just been told.","ex":{"en":"'John phoned to say that his computer wasn't working.' — 'Oh God no.'","cn":"“约翰打电话说他的电脑坏了。”——“噢，天哪，不会吧。”"}},{"pos":"DET-NEG 否定限定词","cn":"没有;丝毫没有","en":"You use no to mean not any or not one person or thing.","ex":{"en":"He had no intention of paying the cash","cn":"他根本没有付钱的打算。"}},{"pos":"DET-NEG 否定限定词","cn":"完全不是;远非","en":"You use no to emphasize that someone or something is not the type of thing mentioned.","ex":{"en":"He is no singer","cn":"他完全没有歌唱天分。"}},{"pos":"ADV 副词","cn":"(用于构成比较级的否定形式)根本不，毫不","en":"You can use no to make the negative form of a comparative.","ex":{"en":"It is to start broadcasting no later than the end of next year","cn":"开播时间不会晚于明年年底。"}},{"pos":"DET-NEG 否定限定词","cn":"(用于形容词和名词前，使其表示相反意义)倒不，并非","en":"You use no in front of an adjective and noun to make the noun group mean its opposite.","ex":{"en":"Sometimes a bit of selfishness, if it leads to greater self-knowledge, is no bad thing","cn":"如果能唤起更多自知之明，有时候一点点自私并非坏事。"}},{"pos":"DET-NEG 否定限定词","cn":"(用于布告或指示中)不准，禁止","en":"No is used in notices or instructions to say that a particular activity or thing is forbidden.","ex":{"en":"The captain turned out the 'no smoking' signs","cn":"队长把“严禁吸烟”的标志牌都翻了过来。"}},{"pos":"N-COUNT 可数名词","cn":"作否定回答者;投反对票者;反对票","en":"A no is a person who has answered 'no' to a question or who has voted against something. No is also used to refer to their answer or vote.","ex":{"en":"According to the latest opinion polls, the noes have 50 percent, the yeses 35 percent","cn":"根据最新的民意测验，有50％的人反对，35％的人赞成。"}},{"pos":"PHRASE 短语","cn":"不可能，无法(做某事)","en":"If you say there is no doing a particular thing, you mean that it is very difficult or impossible to do that thing.","ex":{"en":"There is no going back to the life she had","cn":"她无法再回到从前的生活。"}},{"pos":"","cn":"","en":"not to take no for an answer→see: ; no doubt→see: ; no less→see: ; no less than→see: ; no longer→see: ; in no way→see: ; there's no way→see: ; no way→see: ;"}]},"examples":[{"en":"It's about 70 — no, I'm wrong — 80 kilometres from Rome.","cn":"距离罗马大约是 70，不，不对，是 80 公里。"},{"en":"Can't you give me a straight yes or no? “","cn":"是”还是“否”，你就不能给我个直截了当的回答吗？"}]},"norm":{"media":{"uk":"media/uk/norm__gb_1.mp3","us":"media/us/norm__us_1.mp3"},"oxford":{"phon":"nɔːm","pos":"noun","senses":[{"en":"a situation or a pattern of behaviour that is usual or expected","cn":"常态；正常行为","g":"[singular]","ex":{"en":"The new design is a departure from the norm.","cn":"新的设计打破了常规。"}},{"en":"standards of behaviour that are typical of or accepted within a particular group or society","cn":"规范；行为标准","g":"[plural]","ex":{"en":"social/cultural norms","cn":"社会／文化规范"}},{"en":"a required or agreed standard, amount, etc.","cn":"标准；定额；定量","g":"[countable]","ex":{"en":"detailed education norms for children of particular ages","cn":"针对具体年龄儿童的详细教育标准"}},{"en":"to change something so that it is of the required standard; to establish a required or agreed standard for something","cn":"规范；规定","ex":{"en":"You can use the information to norm the test.","cn":"你可以用这些资料去规范测试。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"行为准则;规范","en":"Norms are ways of behaving that are considered normal in a particular society.","ex":{"en":"...the commonly accepted norms of democracy.","cn":"被人们普遍接受的民主准则"}},{"pos":"N-SING 单数名词","cn":"通例;常规","en":"If you say that a situation is the norm, you mean that it is usual and expected.","ex":{"en":"Families of six or seven are the norm in Borough Park","cn":"在区公园住宅区六口或七口之家十分普遍。"}},{"pos":"N-COUNT 可数名词","cn":"标准;规范","en":"A norm is an official standard or level that organizations are expected to reach.","ex":{"en":"...an agency which would establish European norms and co-ordinate national policies to halt pollution.","cn":"确立各项欧洲环保标准、协调各国政策以阻遏污染的机构"}}]},"examples":[{"en":"Older parents seem to be the norm rather than the exception nowadays.","cn":"人们在年龄较大时才生育子女在今天似乎成了常事，而不是个例。"},{"en":"detailed education norms for children of particular ages","cn":"针对具体年龄儿童的详细教育标准"}]},"nowadays":{"media":{"uk":"media/uk/nowadays__gb_1.mp3","us":"media/us/nowadays__us_1.mp3"},"oxford":{"phon":"ˈnaʊədeɪz","pos":"adverb","senses":[{"en":"at the present time, in contrast with the past","cn":"现今；现在；目前","ex":{"en":"Nowadays most kids prefer going online to reading books.","cn":"现在大多数孩子都喜欢上网而不喜欢阅读。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"如今;现今","en":"Nowadays means at the present time, in contrast with the past.","ex":{"en":"Nowadays it's acceptable for women to be ambitious. But it wasn't then","cn":"如今，女性胸怀大志也能被接受，但那时候不是这样。"}}]},"examples":[{"en":"Nowadays most kids prefer watching TV to reading.","cn":"现在大多数孩子都喜欢看电视而不喜欢阅读。"},{"en":"Nowadays people are rarely shocked by the sex they see on television.","cn":"如今人们在电视上看见性爱镜头不太会感到吃惊了。"}]},"non-standard":{"oxford":{"phon":"ˌnɒn ˈstændəd","pos":"adjective","senses":[{"en":"not considered correct by most educated people","cn":"非标准的；不规范的","ex":{"en":"Standard English and non-standard dialects have much in common.","cn":"标准英语和不规范的方言有许多相同之处。"}},{"en":"not the usual size, type, etc.","cn":"（尺寸、型号等）不标准的，非常用的","ex":{"en":"The paper was of non-standard size.","cn":"这种纸的大小不标准。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不标准的;不规范的","en":"Non-standard things are different from the usual version or type of that thing.","ex":{"en":"...non-standard window shapes","cn":"不标准的窗户形状"}}]},"media":{"uk":"media/uk/non_standard_1_gb_1.mp3","us":"media/us/non_standard_1_us_1.mp3"},"examples":[{"en":"The paper was of non-standard size.","cn":"这种纸的大小不标准。"},{"en":"non-standard dialects","cn":"不规范的方言"}]},"northern":{"media":{"uk":"media/uk/northern__gb_1.mp3","us":"media/us/northern__us_1.mp3"},"oxford":{"phon":"ˈnɔːðən","pos":"adjective","senses":[{"en":"located in the north or facing north; connected with or typical of the north part of the world or a region","cn":"北方的；向北的；北部的","ex":{"en":"the northern slopes of the mountains","cn":"山脉的北坡"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"北的;(在)北部的;来自北部的","en":"Northern means in or from the north of a region, state, or country.","ex":{"en":"Their two children were immigrants to Northern Ireland from Pennsylvania","cn":"他们的两个孩子是从宾夕法尼亚州移民到北爱尔兰的。"}}]},"examples":[{"en":"the northern slopes of the mountains","cn":"山脉的北坡"},{"en":"northern Scotland","cn":"苏格兰北部"}]},"none":{"media":{"uk":"media/uk/none__gb_1.mp3","us":"media/us/none__us_1.mp3"},"oxford":{"phon":"nʌn","pos":"pronoun","senses":[{"en":"not one of a group of people or things; not any","cn":"没有一个；毫无","lab":"formal","ex":{"en":"None of these pens works/work.","cn":"这些钢笔没有一支能用。"}},{"en":"used with the and a comparative to mean ‘not at all’","cn":"（与 the 加比较级连用）一点都不，绝无","ex":{"en":"She told me what it meant at great length but I'm afraid I'm none the wiser.","cn":"她费尽口舌给我解释它的意思，可我恐怕还是不明白。"},"pos":"adverb"},{"en":"used with too and an adjective or adverb to mean ‘not at all’ or ‘not very’","cn":"（与 too 加形容词或副词连用）绝不，不怎么","ex":{"en":"She was looking none too pleased.","cn":"她看上去一点也不高兴。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"QUANT 数量词","cn":"没有一点儿;全无;没有一个(人或物)","en":"None of something means not even a small amount of it. None of a group of people or things means not even one of them.","ex":{"en":"She did none of the maintenance on the vehicle itself","cn":"她对车子本身没有进行半点养护。"}},{"pos":"PHRASE 短语","cn":"同…不沾边;不准;拒绝接受","en":"If you say that someone will have none of something, or is having none of something, you mean that they refuse to accept it.","ex":{"en":"He knew his own mind and was having none of their attempts to keep him at home.","cn":"他心意已决，坚决不答应他们想要将自己留在家中。"}},{"pos":"PHRASE 短语","cn":"只有;除…之外没有","en":"None but means only.","ex":{"en":"None but God will ever know what I suffered","cn":"只有上帝知道我受过什么苦。"}},{"pos":"PHRASE 短语","cn":"(用于形容词或副词前，强调提到的特质不存在)毫无，毫不","en":"You use none too in front of an adjective or adverb in order to emphasize that the quality mentioned is not present.","ex":{"en":"He was none too thrilled to hear from me at that hour","cn":"在那个钟点接到我的电话，他一点也兴奋不起来。"}},{"pos":"PHRASE 短语","cn":"(表示原有的特质现已失去)毫不，一点也不","en":"You use none the to say that someone or something does not have any more of a particular quality than they did before.","ex":{"en":"You could end up committed to yet another savings scheme and none the wiser about managing your finances","cn":"你可能最终又会把钱投入另一个储蓄计划，在理财方面丝毫没有变得明智些。"}},{"pos":"","cn":"","en":"none of your business→see: ; none other than→see: ; second to none→see: ;"}]},"examples":[{"en":"She told me what it meant at great length but I'm afraid I'm none the wiser.","cn":"她费尽口舌给我解释它的意思，可我恐怕还是不明白。"},{"en":"He told me all the news but none of it was very exciting.","cn":"他告诉了我所有的新闻，但没有一件激动人心的。"}]},"norms":{"lemma":"norm","media":{"uk":"media/uk/norm__gb_1.mp3","us":"media/us/norm__us_1.mp3"}},"not":{"media":{"uk":"media/uk/not__gb_1.mp3","us":"media/us/not__us_1.mp3"},"oxford":{"phon":"nɒt","pos":"adverb","senses":[{"en":"used with be, do or have to form the negative of verbs; used to form the negative of modal verbs like can or must","cn":"不（构成动词 be、do、have 和情态动词 can、must 等的否定形式）","ex":{"en":"She did not/didn’t see him.","cn":"她没看见他。"}},{"en":"used to give the following word or phrase a negative meaning, or to reply in the negative","cn":"（否定后面的词或短语，或作否定的回答）不，没有","ex":{"en":"He warned me not to be late.","cn":"他提醒我不要迟到。"}},{"en":"used after hope, expect, believe, etc. to give a negative reply","cn":"（用于 hope、expect、believe 等动词后，作为否定的回答）不，没有","lab":"formal","ex":{"en":"‘Will she be there?’ ‘I hope not.’","cn":"“她会在那儿吗？”“但愿不会。”"}},{"en":"used to show a negative possibility","cn":"（表示否定的可能性）否，或许不","ex":{"en":"I don't know if he's telling the truth or not.","cn":"我不知道他是否说了真话。"}},{"en":"used to say that you do not want something or will not allow something","cn":"（拒绝或不允许）不","ex":{"en":"‘Some more?’ ‘Not for me, thanks.’","cn":"“再来点儿吗？”“我不要了，谢谢。”"}},{"en":"even less than","cn":"连…也不到","ex":{"en":"She was standing not three feet in front of me.","cn":"她站在我前面不到三英尺的地方。"}},{"en":"used to suggest that the opposite of the following word or phrase is true","cn":"（表示与后面的词语意思相反）","ex":{"en":"This could all happen in the not too distant future (= soon).","cn":"这一切都可能在不久的将来发生。"}},{"en":"used to emphasize the opposite of a statement","cn":"才怪（否定刚说过的话）","lab":"humorous, informal，，","ex":{"en":"Well, that sounds like a fun evening—not!","cn":"那听起来是愉快的一晚——才怪！"}}]},"collins":{"senses":[{"pos":"NEG 否定词","cn":"(与动词连用构成否定句)不，非，没有","en":"You use not with verbs to form negative statements.","ex":{"en":"The sanctions are not working the way they were intended","cn":"制裁没有发挥预期的作用。"}},{"pos":"NEG 否定词","cn":"(构成期望得到肯定回答的疑问句)","en":"You use not to form questions to which you expect the answer 'yes'.","ex":{"en":"Haven't they got enough problems there already?","cn":"难道他们那儿的问题还少吗？"}},{"pos":"NEG 否定词","cn":"(通常以 n't 的形式出现在问句中，用于推断某人应已做某事或表示惊讶)","en":"You use not, usually in the form n't, in questions which imply that someone should have done something, or to express surprise that something is not the case.","ex":{"en":"Why didn't you do it months ago?","cn":"几个月以前你为什么不做呢？"}},{"pos":"NEG 否定词","cn":"(通常用 n't 的形式，用于肯定陈述后的附加疑问句)是吗? 不是吗?","en":"You use not, usually in the form n't, in question tags after a positive statement.","ex":{"en":"'It's a nice piece of jewellery though, isn't it?'","cn":"“可这是一件漂亮的首饰，不是吗?”"}},{"pos":"NEG 否定词","cn":"(通常以 n't 的形式，表示礼貌的建议)","en":"You use not, usually in the form n't, in polite suggestions.","ex":{"en":"Actually we do have a position in mind. Why don't you fill out our application?","cn":"实际上我们的确在考虑一个职位，你先填一下我们的求职表好吗？"}},{"pos":"NEG 否定词","cn":"(用于表示对刚提及的单词、词组或从句的否定)不，没有","en":"You use not to represent the negative of a word, group, or clause that has just been used.","ex":{"en":"'Have you found Paula?'—'I'm afraid not, Kate.'","cn":"“你找到葆拉了吗？”——“很遗憾，没有，凯特。”"}},{"pos":"NEG 否定词","cn":"(用于 all 或 every 前，表示部分否定)并非，不是","en":"You can use not in front of 'all' or 'every' when you want to say something that applies only to some members of the group that you are talking about.","ex":{"en":"Not all the money, to put it mildly, has been used wisely","cn":"说得好听些，不是所有的钱都花得是地方。"}},{"pos":"NEG 否定词","cn":"并非(总是…)","en":"If something is not always the case, you mean that sometimes it is the case and sometimes it is not.","ex":{"en":"He didn't always win the arguments, but he often was right","cn":"他并非在争辩中总是能赢，但他经常是对的。"}},{"pos":"NEG 否定词","cn":"(用于 a 或 one 前加强语气)(一个…)也不，(一个…)也没有","en":"You can use not or not even in front of 'a' or 'one' to emphasize that there is none at all of what is being mentioned.","ex":{"en":"The houses are beautiful, but there's no shop, not even a pub to go into","cn":"这些房子很漂亮，但周围没有商店，甚至连一个酒馆都没有。"}},{"pos":"NEG 否定词","cn":"(用于表示距离、时间或其他数量的词前)不到，少于","en":"You can use not in front of a word referring to a distance, length of time, or other amount to say that the actual distance, time, or amount is less than the one mentioned.","ex":{"en":"The tug crossed our stern not fifty yards away","cn":"拖船擦着我们的船尾开了过去，距离不到50码。"}},{"pos":"NEG 否定词","cn":"(用于对比真实和不真实的情况，尤用于可能使人产生误解的陈述)不是","en":"You use not when you are contrasting something that is true with something that is untrue. You use this especially to indicate that people might think that the untrue statement is true.","ex":{"en":"He has his place in the Asian team not because he is white but because he is good","cn":"他在这支亚洲球队中占有一席之地，不是因为他是白人，而是因为他确实出色。"}},{"pos":"NEG 否定词","cn":"(用于not only，not just, not simply 等短语中，强调某事物的真实性，但不是全部事实)","en":"You use not in expressions such as 'not only', 'not just', and 'not simply' to emphasize that something is true, but it is not the whole truth.","ex":{"en":"These movies were not only making money; they were also perceived to be original","cn":"这些电影不仅赚钱，而且被视为具有原创性。"}},{"pos":"PHR-CONJ-SUBORD","cn":"(用于引出否定从句)并不是说，并非","en":"You use not that to introduce a negative clause that contradicts something that the previous statement implies.","ex":{"en":"His death took me a year to get over; not that you're ever really over it","cn":"我用一年时间慢慢接受了他去世的事实，但其实你永远不会真正完全忘掉。"}},{"pos":"CONVENTION 惯用语","cn":"(用于表示强调)一点不，根本没有","en":"Not at all is an emphatic way of saying 'No' or of agreeing that the answer to a question is 'No'.","ex":{"en":"'Sorry. I sound like Abby, don't I?' — 'No. Not at all.'","cn":"“抱歉，我讲起话来像阿比，是不是？”——“不，一点不像。”"}},{"pos":"CONVENTION 惯用语","cn":"不用谢;别客气","en":"Not at all is a polite way of acknowledging a person's thanks.","ex":{"en":"'Thank you very much for speaking with us.' — 'Not at all.'","cn":"“非常感谢您能和我们交谈。”——“不客气。”"}},{"pos":"","cn":"","en":"not half→see: ; if not→see: ; not least→see: ; not to mention→see: ; nothing if not→see: ; not for nothing→see: ; more often than not→see: ;"}]},"examples":[{"en":"‘What did you do at school?’ ‘ Not a lot. ’ “","cn":"你在学校干什么了？” “没做多少事。”"},{"en":"‘Can I throw this out?’ ‘Certainly not.’ “","cn":"我把这个扔了，行吗？” “当然不行。”"}]},"nobility":{"oxford":{"phon":"nəʊˈbɪləti","pos":"noun","senses":[{"en":"people of high social position who have titles such as that of duke or duchess","cn":"贵族","g":"[singular + singular or plural verb]"},{"en":"the quality of being noble in character","cn":"高贵的品质","g":"[uncountable]","lab":"formal","ex":{"en":"The bravery and nobility of these men who died for their country.","cn":"这些为国捐躯的人的勇敢和高尚。"}}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"贵族(阶层)","en":"The nobility of a society are all the people who have titles and belong to a high social class.","ex":{"en":"They married into the nobility and entered the highest ranks of state administration","cn":"他们同贵族阶层联姻，进入了国家最高行政层。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"高尚的品质;高贵的举止","en":"A person's nobility is their noble character and behaviour.","ex":{"en":"...his nobility of character, and his devotion to his country.","cn":"他的高尚品格和对祖国的忠诚"}}]},"media":{"uk":"media/uk/nobility__gb_1.mp3","us":"media/us/nobility__us_1.mp3"},"examples":[{"en":"the nobility of his intentions","cn":"他崇高的志向"}]},"noticeable":{"media":{"uk":"media/uk/noticeable__gb_1.mp3","us":"media/us/noticeable__us_1.mp3"},"oxford":{"phon":"ˈnəʊtɪsəbl","pos":"adjective","senses":[{"en":"easy to see or notice; clear or definite","cn":"显著的；显而易见的","ex":{"en":"The new filing system is a noticeable improvement on the old one.","cn":"这种新的存档系统比过去那种有着显著的改进。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"容易注意到的;显著的;明显的","en":"Something that is noticeable is very obvious, so that it is easy to see, hear, or recognize.","ex":{"en":"It is noticeable that women do not have the rivalry that men have","cn":"显而易见，女性不像男人们那样好勇斗狠。"}}]},"examples":[{"en":"This effect is particularly noticeable in younger patients.","cn":"这种作用在年轻一些的病人身上尤为明显。"},{"en":"Marks were noticeably higher for girls than for boys.","cn":"女孩子的分数明显地高于男孩子。"}]},"nouns":{"lemma":"noun"},"noun":{"oxford":{"phon":"naʊn","pos":"noun","senses":[{"en":"a word that refers to a person (such as Ann or doctor), a place (such as Paris or city) or a thing, a quality or an activity (such as plant, joy or tennis)","cn":"名词","ex":{"en":"‘Car’ is a concrete noun.","cn":"car 是具体名词。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"名词","en":"A noun is a word such as 'car', 'love', or 'Anne' which is used to refer to a person or thing."}]},"media":{"uk":"media/uk/noun__gb_1.mp3","us":"media/us/noun__us_1.mp3"}},"novelty":{"media":{"uk":"media/uk/novelty__gb_1.mp3","us":"media/us/novelty__us_1.mp3"},"oxford":{"phon":"ˈnɒvlti","pos":"noun","senses":[{"en":"the quality of being new, different and interesting","cn":"新奇；新颖；新鲜","g":"[uncountable]","ex":{"en":"It was fun working there at first but the novelty soon wore off (= it became boring).","cn":"开始的时候在那里工作很有趣，但这股新鲜劲很快就过去了。"}},{"en":"a thing, person or situation that is interesting because it is new, unusual or has not been known before","cn":"新奇的事物（或人、环境）","g":"[countable]","ex":{"en":"Electric cars are still something of a novelty.","cn":"电动汽车仍然是一种新鲜玩意儿。"}},{"en":"a small cheap object sold as a toy or a decoration","cn":"廉价小饰物；小玩意儿","g":"[countable]"},{"en":"different and unusual; intended to be humorous and to catch people’s attention","cn":"新奇的；风格独特的","ex":{"en":"a novelty teapot","cn":"新颖独特的茶壶"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"新奇性;新颖","en":"Novelty is the quality of being different, new, and unusual.","ex":{"en":"In the contemporary western world, rapidly changing styles cater to a desire for novelty and individualism.","cn":"在当代西方社会，快速变化的时尚迎合了人们追求新奇和个性的需求。"}},{"pos":"N-COUNT 可数名词","cn":"新奇的事物","en":"A novelty is something that is new and therefore interesting.","ex":{"en":"Seeing people queuing for food was a novelty","cn":"看到人们排队买食品是件新鲜事。"}},{"pos":"N-COUNT 可数名词","cn":"廉价小饰物;小玩意","en":"Novelties are cheap toys, ornaments, or other objects that are sold as presents or souvenirs.","ex":{"en":"At Easter, we give them plastic eggs filled with small toys, novelties and coins.","cn":"复活节时，我们给他们分发塑料彩蛋，里面装着小玩具、新颖的小玩意儿和硬币。"}}]},"examples":[{"en":"It was fun working there at first but the novelty soon wore off (= it became boring).","cn":"开始的时候在那里工作很有趣，但这股新鲜劲很快就过去了。"},{"en":"Electric cars are still something of a novelty.","cn":"电动汽车仍然是一种新鲜玩意儿。"}]},"nods":{"lemma":"nod"},"notice":{"media":{"uk":"media/uk/notice__gb_1.mp3","us":"media/us/notice__us_1.mp3"},"oxford":{"phon":"ˈnəʊtɪs","pos":"verb","senses":[{"en":"to see or hear somebody/something; to become aware of somebody/something","cn":"看（或听）到；注意到；意识到","g":"[intransitive, transitive]","sc":"see/hear","ex":{"en":"People were making fun of him but he didn't seem to notice.","cn":"人们在拿他开玩笑，但他好像没有意识到。"}},{"en":"to pay attention to somebody/something","cn":"注意；留意","g":"[transitive]","sc":"pay/get attention","ex":{"en":"Notice the way the bridge is supported by its suspension cables.","cn":"请留意桥是怎样用吊缆支撑的。"}},{"en":"to get attention from other people","cn":"引人注意","g":"[transitive]","sc":"pay/get attention","ex":{"en":"She wears those strange clothes just to get herself noticed.","cn":"她穿那些奇装异服不过是想引人注意而已。"}},{"en":"a sheet of paper giving written or printed information, usually put in a public place","cn":"通告；布告；通知","g":"[countable]","sc":"giving information","ex":{"en":"There was a notice on the board saying the class had been cancelled.","cn":"布告牌上有一则通知说这堂课取消了。"},"pos":"noun"},{"en":"a board or sign giving information, an instruction or a warning","cn":"公告牌；警示牌","g":"[countable]","sc":"giving information","ex":{"en":"There was a notice saying ‘Keep off the Grass’.","cn":"有一块公告牌，上面写着“勿踏草地”。"},"pos":"noun"},{"en":"a small advertisement or announcement in a newspaper or magazine","cn":"启事；声明","g":"[countable]","sc":"announcing something","ex":{"en":"notices of births, marriages and deaths","cn":"出生喜报、结婚启事和讣告"},"pos":"noun"},{"en":"a short announcement made at the beginning or end of a meeting, a church service, etc.","cn":"（会议、宗教活动等开头或结尾时的）通知","g":"[countable]","sc":"announcing something","ex":{"en":"There are just two notices this week.","cn":"本周只有两项通知。"},"pos":"noun"},{"en":"the fact of somebody paying attention to somebody/something or knowing about something","cn":"注意；理会；察觉","g":"[uncountable]","lab":"formal","sc":"paying attention","ex":{"en":"Don't take any notice of what you read in the papers.","cn":"别在意你在报上看到的东西。"},"pos":"noun"},{"en":"information or a warning given in advance of something that is going to happen","cn":"预告；警告","g":"[uncountable]","sc":"warning","ex":{"en":"You are welcome to come and stay as long as you give us plenty of notice.","cn":"只要你及早通知，我们都欢迎你来住宿。"},"pos":"noun"},{"en":"a formal letter or statement saying that you will or must leave your job or house at the end of a particular period of time","cn":"辞职信；搬迁通知","g":"[uncountable, countable]","lab":"North American English","sc":"when leaving job/house","ex":{"en":"He has handed in his notice.","cn":"他递交了辞呈。"},"pos":"noun"},{"en":"a short article in a newspaper or magazine, giving an opinion about a book, play, etc.","cn":"（报刊上对书、戏剧等的）评论，短评","g":"[countable]","sc":"review of book/play","ex":{"en":"The play got good notices in the national press.","cn":"该剧在全国媒体上引起了广泛关注。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"觉察;注意","en":"If you notice something or someone, you become aware of them.","ex":{"en":"People should not hesitate to contact the police if they've noticed anyone acting suspiciously","cn":"如果发现形迹可疑的人，应该马上报警。"}},{"pos":"N-COUNT 可数名词","cn":"(书面)通知;告示;通告牌","en":"A notice is a written announcement in a place where everyone can read it.","ex":{"en":"Notices in the waiting room requested that you neither smoke nor spit","cn":"候车室的公告牌要求人们不要吸烟和随地吐痰。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"预告;警告;事先声明","en":"If you give notice about something that is going to happen, you give a warning in advance that it is going to happen.","ex":{"en":"Interest is paid monthly. Three months' notice is required for withdrawals","cn":"利息按月支付。提款须提前3个月通知银行。"}},{"pos":"N-COUNT 可数名词","cn":"(报刊上的)启事，声明","en":"A notice is a formal announcement in a newspaper or magazine about something that has happened or is going to happen.","ex":{"en":"I rang The Globe with news of Blake's death, and put notices in the personal column of The Times","cn":"我给环球剧院打电话告知了布莱克的死讯，然后在《泰晤士报》的私人广告栏登了讣告。"}},{"pos":"N-COUNT 可数名词","cn":"(机构发送给相关人员的)通告","en":"A notice is one of a number of letters that are similar or exactly the same which an organization sends to people in order to give them information or ask them to do something.","ex":{"en":"Bonus notices were issued each year from head office to local agents","cn":"分红通告每年由总公司发送至地方代理商。"}},{"pos":"N-COUNT 可数名词","cn":"(报刊上关于戏剧、电影或音乐会的)短评，评论","en":"A notice is a written article in a newspaper or magazine in which someone gives their opinion of a play, film, or concert.","ex":{"en":"Nevertheless, it's good to know you've had good notices, even if you don't read them.","cn":"不过，即便你不看，知道有一些对你的好评也挺好。"}},{"pos":"PHRASE 短语","cn":"随时/接到通知后立即/提前24小时通知","en":"Notice is used in expressions such as 'at short notice', 'at a moment's notice' or 'at twenty-four hours' notice', to indicate that something can or must be done within a short period of time.","ex":{"en":"There's no one available at such short notice to take her class","cn":"只提前这么短的时间通知，找不到人替她的课。"}},{"pos":"PHRASE 短语","cn":"引起(某人)对…的注意;使(某人)察觉到","en":"If you bring something to someone's notice, you make them aware of it.","ex":{"en":"I am so glad that you have brought this to my notice","cn":"我很高兴你让我注意到了这件事情。"}},{"pos":"PHRASE 短语","cn":"引起…注意","en":"If something comes to your notice, you become aware of it.","ex":{"en":"Her work also came to the notice of the French actor-producer Louis Jouvet","cn":"她的作品也引起了法国演员兼制片人路易·茹韦的注意。"}},{"pos":"PHRASE 短语","cn":"没有引起…注意;没有被…察觉","en":"If something escapes your notice, you fail to recognize it or realize it.","ex":{"en":"It hasn't escaped our notice that the hospital has come out of all the proposed changes really quite nicely","cn":"我们注意到医院很好地兑现了所有拟议的变革举措。"}},{"pos":"PHRASE 短语","cn":"直至另行通知","en":"If a situation is said to exist until further notice, it will continue for an uncertain length of time until someone changes it.","ex":{"en":"All flights to Lanchow had been cancelled until further notice.","cn":"所有飞往兰州的航班都已取消，何时恢复另行通知。"}},{"pos":"PHRASE 短语","cn":"通知…离职;给…解雇通知","en":"If an employer gives an employee notice, the employer tells the employee that he or she must leave his or her job within a fixed period of time.","ex":{"en":"The next morning I telephoned him and gave him his notice.","cn":"第二天早晨我给他打了电话，通知他已被解雇。"}},{"pos":"PHRASE 短语","cn":"提出辞职;递交辞呈","en":"If you hand in your notice or give in your notice, you tell your employer that you intend to leave your job soon within a set period of time.","ex":{"en":"He handed in his notice at the bank and ruined his promising career.","cn":"他向银行提出了辞职，毁掉了自己的大好前程。"}},{"pos":"PHRASE 短语","cn":"注意;关注","en":"If you take notice of a particular fact or situation, you behave in a way that shows that you are aware of it.","ex":{"en":"We want the government to take notice of what we think they should do for single parents","cn":"我们希望政府能够关注单亲父母，为他们做一些应该做的事。"}},{"pos":"PHRASE 短语","cn":"不关注;不理会","en":"If you take no notice of someone or something, you do not consider them to be important enough to affect what you think or what you do.","ex":{"en":"They took no notice of him, he did not stand out, he was in no way remarkable","cn":"他们没在意他，他并不突出，一点也不引人注目。"}}]},"examples":[{"en":"( formal ) It will not have escaped your notice that there have been some major changes in the company.","cn":"你肯定会注意到公司已经发生了一些重大的变化。"},{"en":"These protests have really made the government sit up and take notice (= realize the importance of the situation).","cn":"这些抗议活动确实引起了政府的警觉和注意。"}]},"noisy":{"media":{"uk":"media/uk/noisy__gb_1.mp3","us":"media/us/noisy__us_1.mp3"},"oxford":{"phon":"ˈnɔɪzi","pos":"adjective","senses":[{"en":"making a lot of noise","cn":"吵闹的；聒噪的；嘈杂的","ex":{"en":"noisy children/traffic/crowds","cn":"吵闹的孩子；喧闹的交通；嘈杂的人群"}},{"en":"full of noise","cn":"充满噪声的；吵吵闹闹的","ex":{"en":"a noisy classroom/office","cn":"吵闹的教室／办公室"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"喧闹的;嗓门大的;聒噪的","en":"A noisy person or thing makes a lot of loud or unpleasant noise.","ex":{"en":"...my noisy old typewriter","cn":"我那台噪音极大的旧打字机"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满噪音的;嘈杂的","en":"A noisy place is full of a lot of loud or unpleasant noise.","ex":{"en":"It's a noisy place with film clips showing constantly on one of the cafe's giant screens","cn":"这个咖啡馆很嘈杂，室内的一个大屏幕上不停地播放着电影片断。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(为引起注意)吵吵嚷嚷的;哗众取宠的","en":"If you describe someone as noisy, you are critical of them for trying to attract attention to their views by frequently and forcefully discussing them.","ex":{"en":"It might, at last, silence the small but noisy intellectual clique.","cn":"它可能最终会使这个聒噪的知识分子小圈子安静下来。"}}]},"examples":[{"en":"The engine is very noisy at high speed.","cn":"这个发动机转速高时噪音非常大。"},{"en":"The children were playing noisily upstairs.","cn":"孩子们在楼上吵闹地玩耍。"}]},"nod":{"oxford":{"phon":"nɒd","pos":"verb","senses":[{"en":"if you nod, nod your head or your head nods, you move your head up and down to show agreement, understanding, etc.","cn":"点头","g":"[intransitive, transitive]","ex":{"en":"I asked him if he would help me and he nodded.","cn":"我问他能不能帮我一下，他点了点头。"}},{"en":"to move your head down and up once to say hello or goodbye to somebody or to give them a sign to do something","cn":"点头致意；点头示意","g":"[intransitive, transitive]","ex":{"en":"The president nodded to the crowd as he passed in the motorcade.","cn":"当总统的车队经过时，他向人群点头致意。"}},{"en":"to move your head in the direction of somebody/something to show that you are talking about them/it","cn":"（朝…方向）点头（表示所谈论的人或物）","g":"[intransitive]","ex":{"en":"I asked where Steve was and she nodded in the direction of the kitchen.","cn":"我问史蒂夫在哪儿，她朝厨房点了点头。"}},{"en":"to let your head fall forward when you are sleeping in a chair","cn":"打盹；打瞌睡","g":"[intransitive]","ex":{"en":"He sat nodding in front of the fire.","cn":"他坐在火炉前打盹。"}},{"en":"a small quick movement of the head down and up again","cn":"点头","ex":{"en":"to give a nod of approval/agreement/encouragement","cn":"点头表示赞同／同意／鼓励"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"点头;点头赞同","en":"If you nod, you move your head downwards and upwards to show that you are answering 'yes' to a question, or to show agreement, understanding, or approval.","ex":{"en":"'Are you okay?' I asked. She nodded and smiled","cn":"“你没事吧?”我问她。她点点头，笑了。"}},{"pos":"VERB 动词","cn":"(朝…方向)扬头，扬头示意","en":"If you nod in a particular direction, you bend your head once in that direction in order to indicate something or to give someone a signal.","ex":{"en":"'Does it work?' he asked, nodding at the piano","cn":"“它能用吗？”他边问边朝钢琴方向扬了下头。"}},{"pos":"VERB 动词","cn":"(用于打招呼或告别)点头，点头招呼","en":"If you nod, you bend your head once, as a way of saying hello or goodbye.","ex":{"en":"All the girls nodded and said 'Hi'","cn":"所有的女孩都点头招呼道：“嗨!”"}},{"pos":"VERB 动词","cn":"(足球中)顶(球)","en":"In football, if a player nods the ball in a particular direction, they hit the ball there with their head.","ex":{"en":"Taylor leapt up to nod the ball home","cn":"泰勒跳起来头球破门。"}},{"pos":"PHRASE 短语","cn":"点头同意;点头允许","en":"If you give someone the nod, you give them permission to do something.","ex":{"en":"'Keep him outside till I give you the nod.'","cn":"“没我同意，别让他进来。”"}},{"pos":"PHRASE 短语","cn":"(建议)一致接受地，毫无异议地","en":"If a proposal is accepted on the nod, it is accepted without being questioned or argued about.","ex":{"en":"He has always argued that the party cannot be seen to let the treaty through on the nod","cn":"他一直争辩，不能眼看着该党让此条约毫无异议地通过。"}},{"pos":"","cn":"","en":"相关词组：nod off"}]},"media":{"uk":"media/uk/nod__gb_1.mp3","us":"media/us/nod__us_1.mp3"},"examples":[{"en":"The president nodded to the crowd as he passed in the motorcade.","cn":"当总统的车队经过时，他向人群点头致意。"},{"en":"I asked where Steve was and she nodded in the direction of the kitchen.","cn":"我问史蒂夫在哪儿，她朝厨房点了点头。"}]},"nothing":{"media":{"uk":"media/uk/nothing__gb_1.mp3","us":"media/us/nothing__us_1.mp3"},"oxford":{"phon":"ˈnʌθɪŋ","pos":"pronoun","senses":[{"en":"not anything; no single thing","cn":"没有什么；没有一件东西","lab":"British English","ex":{"en":"There was nothing in her bag.","cn":"她的包里什么都没有。"}},{"en":"very little; something that is not at all important or interesting","cn":"几乎什么也没有；无关紧要的东西","ex":{"en":"We did nothing at the weekend.","cn":"我们周末什么也没干。"}}]},"collins":{"senses":[{"pos":"PRON-INDEF-NEG 否定不定代词","cn":"没有什么;没有一件(东西);没有一点","en":"Nothing means not a single thing, or not a single part of something.","ex":{"en":"I've done nothing much since coffee time","cn":"咖啡时间过后，我什么都没干。"}},{"pos":"PRON-INDEF-NEG 否定不定代词","cn":"无关紧要的事物(或人);微不足道的事物(或人)","en":"You use nothing to indicate that something or someone is not important or significant.","ex":{"en":"Because he had always had money it meant nothing to him","cn":"因为他一直不缺钱，所以这对他来说不算什么。"}},{"pos":"PRON-INDEF-NEG 否定不定代词","cn":"极低的价格;相当于免费","en":"If you say that something cost nothing or is worth nothing, you are indicating that it cost or is worth a surprisingly small amount of money.","ex":{"en":"The furniture was threadbare; he'd obviously picked it up for nothing","cn":"这件家具很破旧，显然他是白捡来的了。"}},{"pos":"PRON-INDEF-NEG 否定不定代词","cn":"(用于形容词或带 to 的不定式前表示事物或人不具备所说的性质)没有什么，不是什么","en":"You use nothing before an adjective or 'to'-infinitive to say that something or someone does not have the quality indicated.","ex":{"en":"Around the lake the countryside generally is nothing special","cn":"湖四周的乡村总的来说没有什么特别的。"}},{"pos":"PRON-INDEF-NEG 否定不定代词","cn":"(用于 so + 形容词、副词前或比较级前表示强调)没有别的东西，没有别的事情","en":"You can use nothing before 'so' and an adjective or adverb, or before a comparative, to emphasize how strong or great a particular quality is.","ex":{"en":"Youngsters learn nothing so fast as how to beat the system","cn":"年轻人对如何钻制度的空子学得最快。"}},{"pos":"PHRASE 短语","cn":"要么彻底干完，要么根本不干","en":"You can use all or nothing to say that either something must be done fully and completely or else it cannot be done at all.","ex":{"en":"Either he went through with this thing or he did not; it was all or nothing.","cn":"他要么把这件事做完，要么就不做，只有这两种选择。"}},{"pos":"PHRASE 短语","cn":"(有)比没有好;比没有强","en":"If you say that something is better than nothing, you mean that it is not what is required, but that it is better to have that thing than to have nothing at all.","ex":{"en":"After all, 15 minutes of exercise is better than nothing.","cn":"毕竟，锻炼15分钟比不锻炼好。"}},{"pos":"PHRASE 短语","cn":"(用于名词、不带 to 的不定式或 -ing 形式前)只有，仅仅","en":"You use nothing but in front of a noun, an infinitive without 'to', or an '-ing' form to mean 'only'.","ex":{"en":"All that money brought nothing but sadness and misery and tragedy","cn":"钱带来的只是悲伤、痛苦和灾难。"}},{"pos":"CONVENTION 惯用语","cn":"未发生;不成","en":"You can say 'Nothing doing' when you want to say that something is not happening or cannot be done.","ex":{"en":"Pay now, or nothing doing","cn":"现在付钱，否则不行。"}},{"pos":"PHRASE 短语","cn":"别无他法;只此一计","en":"If you say that there is nothing for it but to take a particular action, you mean that it is the only possible course of action that you can take, even though it might be unpleasant.","ex":{"en":"Much depends on which individual ingredients you choose. There is nothing for it but to taste and to experiment for yourself","cn":"很大程度上取决于你选择哪种配料。除了亲口品尝和动手尝试外，没有别的方法。"}},{"pos":"PHRASE 短语","cn":"极其;非常","en":"You use nothing if not in front of an adjective to indicate that someone or something clearly has a lot of the particular quality mentioned.","ex":{"en":"Professor Fish has been nothing if not professional","cn":"菲什教授一贯表现出很高的职业水准。"}},{"pos":"CONVENTION 惯用语","cn":"没什么;小事情","en":"People sometimes say 'It's nothing' as a polite response after someone has thanked them for something they have done.","ex":{"en":"'Thank you for the wonderful dinner.' — 'It's nothing,' Sarah said","cn":"“谢谢你招待了这么美味的晚餐。”——“这没什么，”萨拉说。"}},{"pos":"PHRASE 短语","cn":"不真实;不可信","en":"If you say about a story or report that there is nothing in it or nothing to it, you mean that it is untrue.","ex":{"en":"It's all rubbish and superstition, and there's nothing in it.","cn":"这都是废话和迷信，不是真的。"}},{"pos":"PHRASE 短语","cn":"不费事;轻而易举","en":"If you say about an activity that there is nothing to it or nothing in it, you mean that it is extremely easy.","ex":{"en":"This device has a gripper that electrically twists off the jar top. Nothing to it","cn":"这个装置有一个能拧开瓶盖的电动钳子，并不复杂。"}},{"pos":"PHRASE 短语","cn":"(比赛或竞争中)水平不相上下，势均力敌","en":"If you say about a contest or competition that there is nothing in it, you mean that two or more of the competitors are level and have an equal chance of winning."},{"pos":"PHRASE 短语","cn":"(用于强调，表示事情让人吃惊或重要)简直，全然","en":"You can use nothing less than to emphasize your next words, often indicating that something seems very surprising or important.","ex":{"en":"What he had in mind amounted to nothing less than a total reversal of the traditional role of the executive","cn":"他头脑中所想的简直就是对管理人员传统角色的彻底颠覆。"}},{"pos":"PHRASE 短语","cn":"并非没有道理;事出有因","en":"If you say that it was not for nothing that something happened, you are emphasizing that there was a very good reason for it to happen.","ex":{"en":"Not for nothing was the plane called 'The widow-maker'","cn":"这种飞机被称作“寡妇机”是事出有因的。"}},{"pos":"PHRASE 短语","cn":"不付代价的收益;不劳而获","en":"If you say that someone is getting something for nothing, you disapprove of the fact that they are getting what they want without doing or giving anything in return.","ex":{"en":"What's wrong with you is that you think you can get something for nothing.","cn":"你的问题是你认为自己可以不劳而获。"}},{"pos":"PHRASE 短语","cn":"绝对没有;绝无此事","en":"Nothing of the sort is used when strongly contradicting something that has just been said.","ex":{"en":"'We're going to talk this over in my office.'—'We're going to do nothing of the sort.'","cn":"“我们打算到我办公室把这件事谈个明白。”——“我们决不同意这么做。”"}},{"pos":"See also:","cn":"","en":"nothing to write home about→see: ; to say nothing of→see: ; nothing short of→see: ; to stop at nothing→see: ; to think nothing of→see: ;"}]},"examples":[{"en":"‘What's that in your pocket?’ ‘Oh, nothing.’ “","cn":"你口袋里装的是什么？” “哦，没什么重要的。”"},{"en":"Nothing else matters to him apart from his job.","cn":"对他来说，除了工作以外，什么事都无关紧要。"}]},"noise":{"media":{"uk":"media/uk/noise__gb_1.mp3","us":"media/us/noise__us_1.mp3"},"oxford":{"phon":"nɔɪz","pos":"noun","senses":[{"en":"a sound, especially when it is loud, unpleasant or frightening","cn":"声音；响声；噪声；吵闹声","g":"[countable, uncountable]","ex":{"en":"There was a rattling noise coming from the back of the car.","cn":"汽车尾部传来咔嗒咔嗒的声音。"}},{"en":"extra electrical or electronic signals that are not part of the signal that is being broadcast or transmitted and which may damage it","cn":"噪声；干扰；电子干扰信号","g":"[uncountable]","lab":"specialist","ex":{"en":"Place the devices as close as possible to the sensors to reduce noise in the signal.","cn":"将设备尽可能靠近传感器放置，以减少信号中的噪声。"}},{"en":"information that is not wanted and that can make it difficult for the important or useful information to be seen clearly","cn":"干扰信息；垃圾信息","g":"[uncountable]","ex":{"en":"There is some noise in the data which needs to be reduced.","cn":"资料里有一些需要删除的不适用信息。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"喧闹声;嘈杂声","en":"Noise is a loud or unpleasant sound.","ex":{"en":"There was too much noise in the room and he needed peace","cn":"屋子里太吵闹，他需要安静。"}},{"pos":"N-COUNT 可数名词","cn":"响声;声音","en":"A noise is a sound that someone or something makes.","ex":{"en":"Sir Gerald made a small noise in his throat.","cn":"杰拉尔德爵士从喉咙里发出了点儿声音。"}},{"pos":"N-PLURAL 复数名词","cn":"(含蓄表明态度的)言语","en":"If someone makes noises of a particular kind about something, they say things that indicate their attitude to it in a rather indirect or vague way.","ex":{"en":"The President took care to make encouraging noises about the future","cn":"总统小心谨慎地表达了他对未来的乐观态度。"}},{"pos":"PHRASE 短语","cn":"随声附和;故作踊跃","en":"If you say that someone makes the right noises or makes all the right noises, you think that they are showing concern or enthusiasm about something because they feel they ought to rather than because they really want to.","ex":{"en":"But at the annual party conference he always made the right noises","cn":"但在每年政党会议上，他总是随声附和。"}}]},"examples":[{"en":"He made all the right noises at the meeting yesterday (= said what people wanted to hear).","cn":"在昨天的会上，他的话句句都合大家的胃口。"},{"en":"We had to shout above the noise of the traffic.","cn":"车辆噪声太大，我们不得不扯着嗓子说话。"}]},"notation":{"media":{"uk":"media/uk/notation__gb_1.mp3","us":"media/us/notation__us_1.mp3"},"oxford":{"phon":"nəʊˈteɪʃn","pos":"noun","senses":[{"en":"a system of signs or symbols used to represent information, especially in mathematics, science and music","cn":"记谱法；标记法","ex":{"en":"scientific/musical notation","cn":"科学记谱法/音乐记谱法"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(音乐、数学等的)标记系统，成套符号","en":"A system of notation is a set of written symbols that are used to represent something such as music or mathematics.","ex":{"en":"Musical notation was conceived for the C major scale and each line and space represents a note in this scale.","cn":"五线谱以C大音阶构成，每一个线和间代表这个音阶的音符。"}}]}},"notch":{"media":{"uk":"media/uk/notch__gb_1.mp3","us":"media/us/notch__us_1.mp3"},"oxford":{"phon":"nɒtʃ","pos":"noun","senses":[{"en":"a level on a scale, often marking quality or achievement","cn":"等级；档次；位阶","ex":{"en":"The quality of the food here has dropped a notch recently.","cn":"这里的饭菜质量最近下降了一级。"}},{"en":"a V-shape or a circle cut in an edge or a surface, sometimes used to keep a record of something","cn":"（表面或边缘的）V 形刻痕，圆形切口","ex":{"en":"For each day he spent on the island, he cut a new notch in his stick.","cn":"他在岛上每过一天，就在手杖上刻一个新的记号。"}},{"en":"each of a series of holes, for example in a belt","cn":"（腰带等的）孔","ex":{"en":"She tightened her belt an extra notch.","cn":"她将腰带又束紧了一格。"}},{"en":"to achieve something such as a win or a high score","cn":"赢取；获得","lab":"informal","ex":{"en":"The team has notched up 20 goals already this season.","cn":"这支球队本赛季已经攻进 20 个球。"},"pos":"verb"},{"en":"to make a small cut in the shape of a V in an edge or a surface","cn":"（在边缘或表面）刻 V 形痕，刻出切口","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"等级;档次","en":"You can refer to a level on a scale of measurement or achievement as a notch .","ex":{"en":"Average earnings in the economy moved up another notch in August","cn":"8月份这个国家的平均收入又上了一个台阶。"}},{"pos":"VERB 动词","cn":"(尤指体育比赛中)赢得，获得","en":"If you notch a success, especially in a sporting contest, you achieve it.","ex":{"en":"Steve Bull notched his 200th goal for Wolves as they beat Leicester 3-0","cn":"史蒂夫·布尔为狼队攻入了他的第200粒进球，他们以3比0击败了莱斯特队。"}},{"pos":"N-COUNT 可数名词","cn":"V形槽口;圆形切口","en":"A notch is a small V-shaped or circular cut in the surface or edge of something.","ex":{"en":"They cut notches in the handle of their pistol for each man they shot.","cn":"他们每杀一个人就在枪托上刻下一个V形记号。"}},{"pos":"","cn":"","en":"相关词组：notch up"}]},"examples":[{"en":"For each day he spent on the island, he cut a new notch in his stick.","cn":"他在岛上每过一天，就在手杖上刻一个新的记号。"},{"en":"The team has notched up 20 goals already this season.","cn":"这支球队本赛季已经攻进 20 个球。"}]},"nor":{"media":{"uk":"media/uk/nor__gb_1.mp3","us":"media/us/nor__us_1.mp3"},"oxford":{"phon":"nɔː(r)","pos":"conjunction, adverb","senses":[{"en":"and not","cn":"也不","lab":"formal","ex":{"en":"She seemed neither surprised nor worried.","cn":"她似乎既不惊讶也不担心。"}},{"en":"used before a positive verb to agree with something negative that has just been said","cn":"（用于肯定动词前，表示同意刚提及的否定命题）也不","ex":{"en":"She doesn't like them and nor does Jeff.","cn":"她不喜欢他们，杰夫也不喜欢。"}}]},"collins":{"senses":[{"pos":"CONJ-COORD-NEG 连词","cn":"(在否定句中用于 neither 之后以引出第二项或几项中的最后一项)也不，也没有","en":"You use nor after 'neither' in order to introduce the second alternative or the last of a number of alternatives in a negative statement.","ex":{"en":"Neither Mr Rose nor Mr Woodhead was available for comment yesterday","cn":"昨天罗斯先生和伍德黑德先生都无暇发表意见。"}},{"pos":"CONJ-COORD-NEG 连词","cn":"(用于否定陈述后，表示该否定句也适用于自己、其他人或其他事物)也不，也没有","en":"You use nor after a negative statement in order to indicate that the negative statement also applies to you or to someone or something else.","ex":{"en":"'None of us has any idea how long we're going to be here.' — 'Nor do I.'","cn":"“我们没有人知道要在这儿呆多久。”——“我也不知道。”"}},{"pos":"CONJ-COORD-NEG 连词","cn":"(用于否定句后，引出另一否定句补充前句)","en":"You use nor after a negative statement in order to introduce another negative statement which adds information to the previous one.","ex":{"en":"Cooking up a quick dish doesn't mean you have to sacrifice flavour. Nor does fast food have to be junk food.","cn":"烹饪快餐并不意味着牺牲风味，快餐也不见得就一定是垃圾食品。"}}]},"examples":[{"en":"He wasn't there on Monday. Nor on Tuesday, for that matter.","cn":"他星期一没在那儿。星期二也一样，也不在。"},{"en":"( formal ) Not a building nor a tree was left standing.","cn":"没有一栋房屋一棵树仍然站着没倒。"}]},"north-east":{"oxford":{"phon":"ˌnɔːθ ˈiːst","pos":"adverb","senses":[{"en":"towards the north-east","cn":"向东北；朝东北","ex":{"en":"This room faces north-east.","cn":"这个房间朝东北。"}},{"en":"nearer to the north-east than something","cn":"东北；东北方；东北地区","ex":{"en":"They live ten miles north-east of Oxford.","cn":"他们住在牛津东北十英里处。"}},{"en":"in or towards the north-east","cn":"东北方的；向东北的；东北部的","ex":{"en":"north-east England","cn":"英格兰东北部"},"pos":"adjective"},{"en":"a north-east wind blows from the north-east","cn":"东北；东北方；东北地区","pos":"adjective"},{"en":"the direction or region at an equal distance between north and east","cn":"东北；东北方；东北地区","pos":"noun"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"东北;东北方","en":"The north-east is the direction which is halfway between north and east.","ex":{"en":"The land to the north-east fell away into meadows.","cn":"陆地向东北方向倾斜延伸成了牧场。"}},{"pos":"N-SING 单数名词","cn":"东北部;东北部地区","en":"The north-east of a place, country, or region is the part which is in the north-east.","ex":{"en":"The north-east, with 60 million people, is the most densely populated part of the United States","cn":"有6,000万人口的东北部是美国人口最稠密的地区。"}},{"pos":"ADV 副词","cn":"向东北","en":"If you go north-east, you travel towards the north-east.","ex":{"en":"The streets were jammed with slow moving traffic, army convoys moving north-east.","cn":"军车队向东北方向行驶，致使街道上车流缓慢，交通拥挤。"}},{"pos":"ADV 副词","cn":"在东北","en":"Something that is north-east of a place is positioned to the north-east of it.","ex":{"en":"This latest attack was at Careysburg, twenty miles north-east of the capital, Monrovia.","cn":"最近的这次袭击发生在首都蒙罗维亚东北20英里处的凯里斯堡。"}},{"pos":"ADJ 形容词","cn":"在东北的;东北部的;向东北的;面朝东北的","en":"The north-east edge, corner, or part of a place is the part which is towards the north-east.","ex":{"en":"These islands of the north-east coast can only be reached in small boats.","cn":"东北部沿海的这些岛屿只有坐小船才能抵达。"}},{"pos":"ADJ 形容词","cn":"(风)从东北方吹来的","en":"A north-east wind is a wind that blows from the north-east.","ex":{"en":"By 9.15 a bitter north-east wind was blowing.","cn":"9点15分时刮起了寒冷的东北风。"}}]},"media":{"uk":"media/uk/north_east_1_gb_1.mp3","us":"media/us/north_east_1_us_1.mp3"}},"notably":{"media":{"uk":"media/uk/notably__gb_1.mp3","us":"media/us/notably__us_1.mp3"},"oxford":{"phon":"ˈnəʊtəbli","pos":"adverb","senses":[{"en":"used for giving a good or the most important example of something","cn":"尤其；特别","ex":{"en":"The house had many drawbacks, most notably its price.","cn":"这房子有很多缺陷，尤其是它的价格。"}},{"en":"to a great degree","cn":"非常；十分；很","ex":{"en":"This has not been a notably successful project.","cn":"这个项目没有取得很大的成功。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"特别;尤其","en":"You use notably to specify an important or typical example of something that you are talking about.","ex":{"en":"The divorce would be granted when more important problems, notably the fate of the children, had been decided","cn":"更为重要的问题，尤其是孩子的问题得到解决后，离婚会获批准。"}},{"pos":"ADV 副词","cn":"(用于强调)显著地","en":"You can use notably to emphasize a particular quality that someone or something has.","ex":{"en":"Old established friends are notably absent, so it's a good opportunity to make new contacts","cn":"老朋友们统统都没有来，因此这是个结交新朋友的好机会。"}}]},"examples":[{"en":"The house had many drawbacks, most notably its price.","cn":"这房子有很多缺陷，尤其是它的价格。"},{"en":"This has not been a notably successful project.","cn":"这个项目没有取得很大的成功。"}]},"notion":{"media":{"uk":"media/uk/notion__gb_1.mp3","us":"media/us/notion__us_1.mp3"},"oxford":{"phon":"ˈnəʊʃn","pos":"noun","senses":[{"en":"an idea, a belief or an understanding of something","cn":"观念；信念；理解","ex":{"en":"a political system based on the notions of equality and liberty","cn":"建立在自由平等观念基础上的政治体系"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"看法;观念;理念","en":"A notion is an idea or belief about something.","ex":{"en":"We each have a notion of just what kind of person we'd like to be","cn":"我们每人都有一个自己想成为什么样的人的想法。"}},{"pos":"N-PLURAL 复数名词","cn":"针头线脑(指针线、纽扣、拉链等小件缝纫用品)","en":"Notions are small articles for sewing, such as buttons, zips, and thread."}]},"examples":[{"en":"I have to reject the notion that greed can be a good thing.","cn":"我不能接受那种认为贪欲也可以是件好事的想法。"},{"en":"She had only a vague notion of what might happen.","cn":"对于可能发生的事她只有一个模糊的概念。"}]},"note":{"media":{"img":["media/ldoce/img/note.jpg","media/pic/money_comp.jpg"],"uk":"media/uk/note__gb_1.mp3","us":"media/us/note__us_1.mp3"},"oxford":{"phon":"nəʊt","pos":"noun","senses":[{"en":"a short piece of writing to help you remember something","cn":"笔记；记录","g":"[countable]","sc":"to remind you","ex":{"en":"Please make a note of the dates.","cn":"请记下日期。"}},{"en":"a short informal letter","cn":"短笺；便条","g":"[countable]","sc":"short letter","ex":{"en":"Just a quick note to say thank you for a wonderful evening.","cn":"仅以此短笺感谢您安排的美好夜晚。"}},{"en":"information that you write down when somebody is speaking, or when you are reading a book, etc.","cn":"（听讲或读书等时的）记录，笔记","g":"[plural]","sc":"information","ex":{"en":"He sat taking notes of everything that was said.","cn":"他坐在那儿记下了所说的每一件事。"}},{"en":"detailed information that is kept about a particular person, topic or situation","cn":"详细记录","g":"[plural]","sc":"information","ex":{"en":"Patients' medical notes have gone missing.","cn":"患者的病历丢失了。"}},{"en":"information about a performance, an actor’s career, a piece of music, etc. printed in a special book or on a record cover, etc.","cn":"（有关演出、演员经历、音乐等的）图书资料或录音等封套介绍","g":"[countable, usually plural]","lab":"British English, becoming old-fashioned，，","sc":"information","ex":{"en":"The booklet has full notes on each artist.","cn":"这本小册子对每一位艺人都有详尽的介绍。"}},{"en":"a short comment on a word or passage in a book","cn":"注释；按语；批注","g":"[countable]","sc":"in book","ex":{"en":"a new edition of ‘Hamlet’, with explanatory notes","cn":"附注释的新版《哈姆雷特》"}},{"en":"a piece of paper money","cn":"纸币；钞票","g":"[countable]","lab":"British English","sc":"money","ex":{"en":"a £5 note","cn":"一张面值为 5 英镑的纸币"}},{"en":"a single sound of a particular length and pitch (= how high or low a sound is), made by the voice or a musical instrument; the written or printed sign for a musical note","cn":"单音；音符","g":"[countable]","sc":"in music","ex":{"en":"He played the first few notes of the tune.","cn":"他演奏了这支曲子开始的几个音。"}},{"en":"a particular quality in something, for example in somebody’s voice or the atmosphere at an event; a comment on something with a particular quality","cn":"特征；口气；调子；气氛","g":"[singular]","sc":"quality","ex":{"en":"There was a note of amusement in his voice.","cn":"他的语气中有觉得好笑的意味。"}},{"en":"an official document with a particular purpose","cn":"正式文件；票据；证明书","g":"[countable]","sc":"official document","ex":{"en":"a sick note from your doctor","cn":"医生开具的病假证明"}},{"en":"an official letter from the representative of one government to another","cn":"（外交文书）照会；通牒","g":"[countable]","lab":"specialist","sc":"official document","ex":{"en":"an exchange of diplomatic notes","cn":"外交照会的互换"}},{"en":"to notice or pay careful attention to something","cn":"注意；留意","ex":{"en":"Note the fine early Baroque altar inside the chapel.","cn":"注意小教堂里精致的早期巴罗克风格的祭坛。"},"pos":"verb"},{"en":"to mention something because it is important or interesting","cn":"指出；特别提到","ex":{"en":"There are a few points here that are worth noting.","cn":"这里有几点值得一提。"},"pos":"verb"},{"en":"to record something in writing","cn":"记录；记下","ex":{"en":"As he noted in his diary on 19 November…","cn":"正如他在 11 月 19 日的日记中所记录…"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"便条;便笺","en":"A note is a short letter.","ex":{"en":"Stevens wrote him a note asking him to come to his apartment","cn":"史蒂文斯给他写了张便条，请他去自己的公寓。"}},{"pos":"N-COUNT 可数名词","cn":"记录;笔记","en":"A note is something that you write down to remind yourself of something.","ex":{"en":"I knew that if I didn't make a note I would lose the thought so I asked to borrow a pen or pencil","cn":"我知道如果我不把这个想法记下来就会忘记，所以我找人借了支笔。"}},{"pos":"N-COUNT 可数名词","cn":"(书或文章的)按语，注释，说明","en":"In a book or article, a note is a short piece of additional information.","ex":{"en":"See Note 16 on p. 223.","cn":"参见第223页的注释16。"}},{"pos":"N-COUNT 可数名词","cn":"票据;单据;证明书","en":"A note is a short document that has to be signed by someone and that gives official information about something.","ex":{"en":"Since Mr Bennett was going to need some time off work, he asked for a sick note","cn":"因为贝内特先生要请假一段时间，他请医生开了病假条。"}},{"pos":"N-COUNT 可数名词","cn":"纸币;钞票","en":"You can refer to a banknote as a note .","ex":{"en":"They exchange traveller's cheques at a different rate from notes.","cn":"他们兑换旅行支票时依据的汇率跟兑换现钞时不同。"}},{"pos":"N-COUNT 可数名词","cn":"音符","en":"In music, a note is the sound of a particular pitch, or a written symbol representing this sound.","ex":{"en":"She has a deep voice and doesn't even try for the high notes","cn":"她嗓音低沉，从没试过高音。"}},{"pos":"N-SING 单数名词","cn":"(说话的)声调，语气","en":"You can use note to refer to a particular quality in someone's voice that shows how they are feeling.","ex":{"en":"There is an unmistakable note of nostalgia in his voice when he looks back on the early years of the family business","cn":"他回忆早些年的家族生意时，无疑是带着一种怀旧的语气的。"}},{"pos":"N-SING 单数名词","cn":"调子;感觉;印象;气氛","en":"You can use note to refer to a particular feeling, impression, or atmosphere.","ex":{"en":"Yesterday's testimony began on a note of passionate but civilized disagreement","cn":"昨天的作供是在激烈但文明地表达分歧的氛围中开始的。"}},{"pos":"VERB 动词","cn":"留意到;意识到","en":"If you note a fact, you become aware of it.","ex":{"en":"The White House has noted his promise to support any attack that was designed to enforce the UN resolutions","cn":"白宫已经注意到他承诺支持所有旨在贯彻联合国决议的打击。"}},{"pos":"VERB 动词","cn":"注意;留意","en":"If you tell someone to note something, you are drawing their attention to it.","ex":{"en":"Note the statue to Sallustio Bandini, a prominent Sienese","cn":"请看这座萨卢斯蒂奥·班迪尼的雕像，他是一位杰出的锡耶纳人。"}},{"pos":"VERB 动词","cn":"强调指出;特别提到","en":"If you note something, you mention it in order to draw people's attention to it.","ex":{"en":"The report notes that export and import volumes picked up in leading economies","cn":"报告特别指出经济大国的进出口量攀升。"}},{"pos":"VERB 动词","cn":"记录;记下","en":"When you note something, you write it down as a record of what has happened.","ex":{"en":"'He has had his tonsils out and has been ill, too,' she noted in her diary","cn":"“他切除了扁桃体，一直病着，”她在日记里写道。"}},{"pos":"PHR-RECIP 相互短语","cn":"交换意见;交流情况","en":"If you compare notes with someone on a particular subject, you talk to them and find out whether their opinion, information, or experience is the same as yours.","ex":{"en":"The women were busily comparing notes on the queen's outfit","cn":"女人们忙着交换对女王衣着的看法。"}},{"pos":"PHRASE 短语","cn":"显要的;有名的","en":"Someone or something that is of note is important, worth mentioning, or well-known.","ex":{"en":"...politicians of note","cn":"政要"}},{"pos":"PHRASE 短语","cn":"表达…的情感;带有…的印象;营造…的氛围","en":"If someone or something strikes a particular note or sounds a particular note, they create a particular feeling, impression, or atmosphere.","ex":{"en":"Before his first round of discussions, Mr Baker sounded an optimistic note","cn":"第一轮讨论前，贝克先生听上去还比较乐观。"}},{"pos":"PHRASE 短语","cn":"留心;注意","en":"If you take note of something, you pay attention to it because you think that it is important or significant.","ex":{"en":"Take note of the weather conditions","cn":"留心一下天气状况。"}},{"pos":"","cn":"","en":"to make a mental note→see: ;"},{"pos":"","cn":"","en":"相关词组：note down"}]},"examples":[{"en":"The sleeve notes include a short biography of the performers on this recording.","cn":"封套上的介绍包括本唱片中的演奏者生平简介。"},{"en":"Note the fine early Baroque altar inside the chapel.","cn":"注意小教堂里精致的早期巴罗克风格的祭坛。"}]},"non-humans":{"lemma":"non-human"},"normal":{"media":{"uk":"media/uk/normal__gb_1.mp3","us":"media/us/normal__us_1.mp3"},"oxford":{"phon":"ˈnɔːml","pos":"adjective","senses":[{"en":"typical, usual or ordinary; what you would expect","cn":"典型的；正常的；一般的","ex":{"en":"quite/perfectly (= completely) normal","cn":"相当／完全正常"}},{"en":"physically and mentally healthy","cn":"（身心）健康的","ex":{"en":"She seemed perfectly normal to me.","cn":"她对我来说似乎很正常。"}},{"en":"the usual or average state, level or standard","cn":"常态；通常标准；一般水平","g":"[uncountable]","ex":{"en":"The rainfall has been above normal for the time of year.","cn":"降雨量一直高于这个时节的正常水平。"},"pos":"noun"},{"en":"a person who is ordinary or healthy","cn":"正常人；健康的人","g":"[countable]","lab":"informal","ex":{"en":"Loads of people, from celebrities to normals, can be funny on Twitter.","cn":"从名人到普通人，很多人都可以在 Twitter 上搞笑。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"正常的;通常的;平常的","en":"Something that is normal is usual and ordinary, and is what people expect.","ex":{"en":"He has occasional injections to maintain his good health but otherwise he lives a normal life","cn":"他偶尔要注射药物保持身体健康，但除此之外他生活一切正常。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"身体健康的;精神正常的","en":"A normal person has no serious physical or mental health problems.","ex":{"en":"Statistics indicate that depressed patients are more likely to become ill than are normal people","cn":"统计显示抑郁症患者比正常人更容易生病。"}}]},"examples":[{"en":"Divorce is complicated enough in normal circumstances , but this situation is even worse.","cn":"在一般情况下，离婚已经够复杂了，但这一次情况更糟。"},{"en":"It's normal to feel tired after such a long trip.","cn":"这样长途旅行之后感到疲劳是正常的。"}]},"nourishment":{"media":{"uk":"media/uk/nourishment__gb_1.mp3","us":"media/us/nourishment__us_1.mp3"},"oxford":{"phon":"ˈnʌrɪʃmənt","pos":"noun","senses":[{"en":"food that is needed to stay alive, grow and stay healthy","cn":"营养；营养品","lab":"figurative","ex":{"en":"Can plants obtain adequate nourishment from such poor soil?","cn":"土壤这样贫瘠，植物能获得足够的养分吗？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"食物;滋养品;营养","en":"If something provides a person, animal, or plant with nourishment, it provides them with the food that is necessary for life, growth, and good health.","ex":{"en":"The mother provides the embryo with nourishment and a place to grow","cn":"母亲为胎儿提供营养和成长的空间。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"滋养;吸收营养","en":"The action of nourishing someone or something, or the experience of being nourished, can be referred to as nourishment .","ex":{"en":"Sugar gives quick relief to hunger but provides no lasting nourishment.","cn":"糖能快速缓解饥饿感，但不能提供持久的营养。"}}]},"examples":[{"en":"Can plants obtain adequate nourishment from such poor soil?","cn":"土壤这样贫瘠，植物能获得足够的养分吗？"},{"en":"( figurative ) As a child, she was starved of intellectual nourishment.","cn":"她小时候缺乏吸取知识的机会。"}]},"nonverbals":{},"now":{"media":{"uk":"media/uk/now__gb_1.mp3","us":"media/us/now__us_1.mp3"},"oxford":{"phon":"naʊ","pos":"adverb","senses":[{"en":"(at) the present time","cn":"现在；目前；此刻","ex":{"en":"Where are you living now?","cn":"你现在住在哪里？"}},{"en":"at or from this moment, but not before","cn":"现在；从现在开始","ex":{"en":"Start writing now.","cn":"现在开始写吧。"}},{"en":"used to show that you are annoyed about something","cn":"（表示恼火）","lab":"informal","ex":{"en":"Now they want to tax food!","cn":"他们竟然要对食品收税！"}},{"en":"used to get somebody’s attention before changing the subject or asking them to do something","cn":"（改变话题或要对方做某事前，引起对方注意）喂，哎，嗨","ex":{"en":"Now, listen to what she's saying.","cn":"嗨，听听她在讲什么。"}},{"en":"because the thing mentioned is happening or has just happened","cn":"既然；由于","ex":{"en":"Now that the kids have left home we've got a lot of extra space.","cn":"孩子们都离开家了，我们住着就更宽绰了。"},"pos":"conjunction"},{"en":"National Organization for Women","cn":"时而…时而…","pos":""}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"现在;如今","en":"You use now to refer to the present time, often in contrast to a time in the past or the future.","ex":{"en":"She's a widow now","cn":"她现在是寡妇。"}},{"pos":"ADV 副词","cn":"马上;立刻","en":"If you do something now, you do it immediately.","ex":{"en":"I'm sorry, but I must go now","cn":"很抱歉我得马上走了。"}},{"pos":"CONJ-SUBORD 连词","cn":"既然;由于","en":"You use now or now that to indicate that an event has occurred and as a result something else may or will happen.","ex":{"en":"Now you're settled, why don't you take up some serious study?","cn":"既然你已经安顿下来了，为什么不开始正经地学点东西呢？"}},{"pos":"ADV 副词","cn":"这一来;这下","en":"You use now to indicate that a particular situation is the result of something that has recently happened.","ex":{"en":"Mrs Chandra has received one sweater for each of her five children and says that the winter will not be so hard now","cn":"钱德拉夫人已经收到了5个孩子每人一件的毛衣，她说这下冬天就不那么难挨了。"}},{"pos":"ADV 副词","cn":"(用于讲述故事或过去的事情)这时，这会儿","en":"In stories and accounts of past events, now is used to refer to the particular time that is being written or spoken about.","ex":{"en":"She felt a little better now","cn":"这时她觉得好点儿了。"}},{"pos":"ADV 副词","cn":"到现在;迄今","en":"You use now in statements which specify the length of time up to the present that something has lasted.","ex":{"en":"They've been married now for 30 years","cn":"到现在他们已经结婚30年了。"}},{"pos":"ADV 副词","cn":"(引起听者的注意或改变话题)喂，喏，好","en":"You say 'Now' or 'Now then' to indicate to the person or people you are with that you want their attention, or that you are about to change the subject.","ex":{"en":"'Now then,' Max said, 'to get back to the point.'","cn":"“好吧”，马克斯说,“回到正题上来。”"}},{"pos":"ADV 副词","cn":"(用于考虑接下来想说的内容)哦，嗯","en":"Some people say 'Now' when they are thinking of what to say next.","ex":{"en":"Now, er, dogs can live to fifteen","cn":"哦，狗能活15年。"}},{"pos":"ADV 副词","cn":"(用于委婉地强调请求或命令)好，行","en":"You use now to give a slight emphasis to a request or command.","ex":{"en":"Come on now. You know you must be hungry","cn":"好，来吧，你肯定已经饿了。"}},{"pos":"ADV 副词","cn":"(引出与已讲述内容有关的信息及继续讲述之前需要了解的信息)你看，喏","en":"You can say 'Now' to introduce information which is relevant to the part of a story or account that you have reached, and which needs to be known before you can continue.","ex":{"en":"My son went to Almeria in Southern Spain. Now he and his wife are people who love a quiet holiday","cn":"我儿子去了西班牙南部的阿尔梅里亚，你看，他和妻子是喜欢过安静假期的那种人。"}},{"pos":"ADV 副词","cn":"(引出对照)然而，不过","en":"You say 'Now' to introduce something which contrasts with what you have just said.","ex":{"en":"Now, if it was me, I'd want to do more than just change the locks","cn":"不过，如果是我，我要做的就不仅仅是换锁了。"}},{"pos":"PHRASE 短语","cn":"时而;有时","en":"If you say that something happens now and then or every now and again, you mean that it happens sometimes but not very often or regularly.","ex":{"en":"My father has a collection of magazines to which I return every now and then","cn":"我爸爸收藏了很多杂志，我有时会翻看一下。"}},{"pos":"PHRASE 短语","cn":"很快;不久;随时","en":"If you say that something will happen any day now ,any moment now, or any time now, you mean that it will happen very soon.","ex":{"en":"Jim expects to be sent to Europe any day now","cn":"吉姆预计随时会被派到欧洲去。"}},{"pos":"PHRASE 短语","cn":"(用于转换话题或播报新活动)下面","en":"People such as television presenters sometimes use now for when they are going to start talking about a different subject or presenting a new activity.","ex":{"en":"And now for something completely different","cn":"下面是完全不同的事情。"}},{"pos":"PHRASE 短语","cn":"刚才;方才","en":"Just now means a very short time ago.","ex":{"en":"You looked pretty upset just now","cn":"你刚才看上去挺难过的。"}},{"pos":"PHRASE 短语","cn":"此刻;目前","en":"You use just now when you want to say that a particular situation exists at the time when you are speaking, although it may change in the future.","ex":{"en":"I'm pretty busy just now","cn":"我现在特别忙。"}},{"pos":"PHRASE 短语","cn":"机不可失;勿失良机;错过这村没这店","en":"If you say 'It's now or never', you mean that something must be done immediately, because if it is not done immediately there will not be another chance to do it.","ex":{"en":"It's now or never, so make up your mind","cn":"机不可失，下决心吧。"}},{"pos":"CONVENTION 惯用语","cn":"(用于劝慰他人)好啦，好啦;得啦，得啦","en":"You can say 'now, now' as a friendly way of trying to comfort someone who is upset or distressed.","ex":{"en":"'I figure it's all over.'—'Now, now. You did just fine.'","cn":"“我想都过去了。”——“好啦，好啦，你做得还不错。”"}},{"pos":"CONVENTION 惯用语","cn":"(用于友好地告诫别人)算了，算了;好了，好了","en":"You can say 'Now, then' or 'Now, now' when you want to give someone you know well a friendly warning not to behave in a particular way.","ex":{"en":"Now then, no unpleasantness, please","cn":"好了，别争了，好吗?"}}]},"examples":[{"en":"Her moods kept changing — now happy, now sad.","cn":"她的情绪总是变幻不定，时而欢喜，时而忧伤。"},{"en":"‘Yes, but Dad … ’ ‘Now what?’ “","cn":"是的，可是爸爸 … ” “又怎么了？”"}]},"noting":{"lemma":"note"},"noticed":{"lemma":"notice"},"notes":{"lemma":"note"},"novels":{"lemma":"novel"},"noises":{"lemma":"noise"},"notions":{"lemma":"notion"},"nonstop":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不停的;不间断的;直达的","en":"Something that is non-stop continues without any pauses or interruptions.","ex":{"en":"Many US cities now have non-stop flights to Aspen.","cn":"美国很多城市现在都有直达阿斯彭的航班。"}}]},"media":{"uk":"media/ldoce/hwd/bre/e/nonstop0205.mp3","us":"media/ldoce/hwd/ame/5/nonstop.mp3"},"examples":[{"en":"a nonstop flight to Los Angeles","cn":"直飞洛杉矶的航班"}]},"notations":{"lemma":"notation"},"nonprofit":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非营利的","en":"A non-profit organization is one which is not run with the aim of making a profit.","ex":{"en":"Her center is typical of many across the country — a non-profit organization that cares for about 50 children.","cn":"她的中心照顾着大约50名儿童，是全国众多非营利机构的典型代表。"}}]},"oxford":{"phon":"ˌnɒnˈprɒfɪt","pos":"noun","senses":[{"en":"an organization that does not aim to make a profit","cn":"非营利组织","ex":{"en":"working for an environmental nonprofit","cn":"为环保非营利组织工作"}}]}},"novelists":{"lemma":"novelist"},"normality":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"正常状态;常态","en":"Normality is a situation in which everything is normal.","ex":{"en":"A semblance of normality has returned with people going to work and shops reopening.","cn":"随着人们开始上班，商店重新开张，表面上一切又恢复了正常。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a situation gets back to normal or returns to normal , it becomes normal again after a period when it was not normal","cn":""},{"en":"a situation in which everything is normal and exactly how you would expect it to be","cn":""},{"en":"a situation in which things happen in the usual or expected way","cn":"正常状态"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"When something happens that shakes up your life, you probably look forward to a return to normality , meaning the usual happenings of everyday life."}]},"collocations":{"phrases":["VERB + NORMALITY restore, return to","PHRASES a return to normality A complete return to normality may take weeks. | some semblance of normality By now any semblance of normality"]},"media":{"uk":"media/ldoce/hwd/bre/e/normality_las2_br.mp3","us":"media/ldoce/hwd/ame/d/normality.mp3"},"examples":[{"en":"They are hoping for a return to normality now that the war is over.","cn":"既然战争结束了，他们希望一切都恢复常态。"},{"en":"We’re hoping for a return to normality as soon as possible.","cn":"我们希望尽快恢复正常。"}],"oxford":{"phon":"nɔːˈmæləti","pos":"noun","senses":[{"en":"a situation where everything is normal or as you would expect it to be","cn":"常态；正常的形势","ex":{"en":"They are hoping for a return to normality now that the war is over.","cn":"既然战争结束了，他们希望一切都恢复常态。"}}]}},"nomination":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(选举、职务竞争中的)提名","en":"A nomination is an official suggestion of someone as a candidate in an election or for a job.","ex":{"en":"...his candidacy for the Republican presidential nomination.","cn":"他参加共和党总统提名角逐的候选资格"}},{"pos":"N-COUNT 可数名词","cn":"(奖项的)提名","en":"A nomination for an award is an official suggestion that someone or something should be given that award.","ex":{"en":"They say he's certain to get a nomination for best supporting actor","cn":"他们说他肯定能获得最佳男配角奖的提名。"}},{"pos":"N-VAR 可变名词","cn":"任命;指定","en":"The nomination of someone to a particular job or position is their appointment to that job or position.","ex":{"en":"They opposed the nomination of a junior officer to the position of Inspector General of Police","cn":"他们反对任命一名下级警官担任警务总监。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of officially suggesting someone or something for a position, duty, or prize, or the fact of being suggested for it","cn":"提名"},{"en":"the name of a book, film, actor etc that has been suggested to receive an honour or prize 〔","cn":"书﹑电影﹑演员等获奖的〕提名"},{"en":"the act of giving someone a particular job, or the fact of being given that job","cn":"任命﹐指定"}]},"collocations":{"phrases":["ADJ. presidential | Democratic, Republican, etc. | Oscar, etc.","VERB + NOMINATION secure, win | stand for She is standing for the Democratic Party presidential nomination. | accept | withdraw | support | ","NOMINATION + NOUN form, paper | process","PREP. ~ as She has withdrawn her nomination as chairman. | ~ for his nomination for the Best Actor award | ~ to He will not accept nominatio"]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41nomination.mp3","us":"media/ldoce/hwd/ame/a/nomination.mp3"},"examples":[{"en":"Membership of the club is by nomination only.","cn":"俱乐部的会员资格仅可通过推荐获得。"},{"en":"He won the nomination as Democratic candidate for the presidency.","cn":"他赢得了民主党总统候选人的提名。"}],"oxford":{"phon":"ˌnɒmɪˈneɪʃn","pos":"noun","senses":[{"en":"the act of suggesting or choosing somebody as a candidate in an election, or for a job or an award; the fact of being suggested for this","cn":"提名；推荐；任命；指派","ex":{"en":"Membership of the club is by nomination only.","cn":"俱乐部的会员资格仅可通过推荐获得。"}}]}},"notification":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"正式通知;正式通告","en":"If you are given notification of something, you are officially informed of it.","ex":{"en":"Names of the dead and injured are being withheld pending notification of relatives","cn":"在正式通知亲属前，伤亡人员名单暂时保密。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"official information about something","cn":"通知，通告"},{"en":"prior/advance notification I was given no prior notification.","cn":"我事先没有接到通知。 notification of You should receive notification of the results within a week. 你应该会在一周内接到有关结果的通知。 official/wri"}]},"collocations":{"phrases":["ADJ. formal, official, written | advance, prior","VERB + NOTIFICATION have, receive | give (sb)","PREP. without ~ The police are entitled to inspect the premises without notification. | ~ of They failed to give notification of their inten"]},"media":{"uk":"media/ldoce/hwd/bre/6/notification0205.mp3","us":"media/ldoce/hwd/ame/3/notification.mp3"},"examples":[{"en":"You should receive (a) notification of our decision in the next week.","cn":"关于我们的决定，下周你会接到通知。"},{"en":"advance/prior notification (= telling sb in advance about sth)","cn":"预先通告"}],"oxford":{"phon":"ˌnəʊtɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"official information of something; the act of giving or receiving this information","cn":"通知；通告；告示","g":"[uncountable, countable]","lab":"formal","ex":{"en":"advance/prior notification (= telling somebody in advance about something)","cn":"预先通告"}},{"en":"an automated message sent by an app to inform the user of a new message, update, etc.","cn":"（提醒社交媒体账号上有更新的）通知信息","g":"[countable]","ex":{"en":"If you're serious about doing a digital detox, you have to resist checking your notifications.","cn":"如果你真的想进行数字戒毒，你就必须抵制检查你的通知。"}}]}},"nourish":{"collins":{"senses":[{"pos":"VERB 动词","cn":"给…提供营养;滋养","en":"To nourish a person, animal, or plant means to provide them with the food that is necessary for life, growth, and good health.","ex":{"en":"The food she eats nourishes both her and the baby.","cn":"她吃的食物给她和婴儿提供了营养。"}},{"pos":"VERB 动词","cn":"滋长，怀有(感情、信念等)","en":"To nourish something such as a feeling or belief means to allow or encourage it to grow.","ex":{"en":"Journalists on the whole don't create public opinion. They can help to nourish it.","cn":"大体说来记者不制造舆论。他们会助长舆论。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give a person or other living thing the food and other substances they need in order to live, grow, and stay healthy","cn":"滋养﹔给…营养"},{"en":"to keep a feeling, idea, or belief strong or help it to grow stronger","cn":"保持﹐怀有﹔培养〔感情﹑观念或信念〕"}]},"vocab":{"pos":"v","senses":[{"en":"When you nourish your imagination or your body, you give it what it needs to stay healthy and flourish (hey, that rhymes!)."}]},"collocations":{"phrases":["PHRASES properly/well nourished Patients recover quickly if they are well nourished."]},"media":{"uk":"media/ldoce/hwd/bre/d/nourish0205.mp3","us":"media/ldoce/hwd/ame/8/nourish.mp3"},"examples":[{"en":"By investing in education, we nourish the talents of our children.","cn":"我们通过教育投资，培养孩子们的才能。"},{"en":"All the children were well nourished and in good physical condition.","cn":"所有这些孩子都营养良好，身体健康。"}],"oxford":{"phon":"ˈnʌrɪʃ","pos":"verb","senses":[{"en":"to keep a person, an animal or a plant alive and healthy with food, etc.","cn":"抚养；滋养；养育","ex":{"en":"All the children were well nourished and in good physical condition.","cn":"所有这些孩子都营养良好，身体健康。"}},{"en":"to allow a feeling, an idea, etc. to develop or grow stronger","cn":"培养，促进（情绪、观点等）","lab":"formal","ex":{"en":"By investing in education, we nourish the talents of our children.","cn":"我们通过教育投资，培养孩子们的才能。"}}]}},"nostalgia":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指对极幸福时光的)怀念;怀旧;念旧","en":"Nostalgia is an affectionate feeling you have for the past, especially for a particularly happy time.","ex":{"en":"He might be influenced by nostalgia for his happy youth","cn":"也许是对年轻时幸福时光的怀恋影响了他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you remember something that happened, something you did, or someone or something you used to know, the thought of them comes back into your mind","cn":""},{"en":"to think about something that happened in the past because you want to remember it","cn":""},{"en":"to deliberately remember a particular fact, event, or situation from the past in order to tell someone about it, especially in a law court or other official situation","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Think of the noun, nostalgia, when you long for the good old days of the past."}]},"collocations":{"phrases":["ADJ. great | pure an evening of pure nostalgia","QUANT. wave A wave of nostalgia came over him.","VERB + NOSTALGIA feel He thought back to his time as a student and felt no nostalgia for any of it. | evoke | indulge in, wallow in","NOSTALGIA + NOUN buff Nostalgia buffs gathered for the auction of wartime memorabilia. | trip The college reunion was a great nostalgia trip","PREP. with ~ I remember it with great nostalgia. | ~ for She felt great nostalgia for the old way of life.","PHRASES a feeling/sense of nostalgia"]},"media":{"uk":"media/ldoce/hwd/bre/f/nostalgia0205.mp3","us":"media/ldoce/hwd/ame/1/nostalgia.mp3"},"examples":[{"en":"She is filled with nostalgia for her own college days.","cn":"她对自己的大学时代充满了怀念之情。"},{"en":"I feel quite nostalgic for the place where I grew up.","cn":"我很怀念我成长的地方。"}],"oxford":{"phon":"nɒˈstældʒə","pos":"noun","senses":[{"en":"a sad feeling mixed with pleasure when you think of happy times in the past","cn":"怀旧；念旧","ex":{"en":"a sense/wave/pang of nostalgia","cn":"怀旧感；一阵强烈的怀旧之情"}}]}},"nominee":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"被提名者;候选人","en":"A nominee is someone who is nominated for a job, position, or award.","ex":{"en":"His nominee for vice president was elected only after a second ballot","cn":"他提名的副总统在两轮投票后才当选。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has been officially suggested for an important position, duty, or prize","cn":"被提名者"}]},"vocab":{"pos":"n","senses":[{"en":"A nominee is someone running for office. You could be a nominee for student council or for the presidency."}]},"collocations":{"phrases":["ADJ. presidential | Democratic, Republican Party, etc. | Oscar, etc.","VERB + NOMINEE appoint","PREP. through a/the ~ They were acting through nominees. | ~ for the nominees for Best Director"]},"media":{"uk":"media/ldoce/hwd/bre/8/nominee0205.mp3","us":"media/ldoce/hwd/ame/c/nominee.mp3"},"examples":[{"en":"a presidential nominee","cn":"被提名为总统候选人的人"},{"en":"an Oscar nominee","cn":"获得奥斯卡提名的人"}],"oxford":{"phon":"ˌnɒmɪˈniː","pos":"noun","senses":[{"en":"a person who has been formally suggested for a job, a prize, etc.","cn":"被提名人；被任命者","ex":{"en":"He was chosen as the party's presidential nominee.","cn":"他获推举角逐该党的总统候选人席位。"}},{"en":"a person in whose name money is invested in a company, etc.","cn":"（投资等的）名义持有人","lab":"business","ex":{"en":"They were acting through nominees.","cn":"他们正通过名义持有人行事。"}}]}},"novelist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小说家","en":"A novelist is a person who writes novels.","ex":{"en":"...a romantic novelist.","cn":"浪漫派小说家"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who writes books, stories, or articles in as a job","cn":""},{"en":"someone who writes books, especially works of literature, or someone who wrote a particular book","cn":""},{"en":"someone who writes books about imaginary people or events","cn":""}]},"collocations":{"phrases":["ADJ. great, leading one of the country's leading contemporary novelists | famous | best-selling, popular his ambition to become a best-selli","NOVELIST + VERB write sth A prolific novelist, she wrote more than forty books."]},"media":{"uk":"media/ldoce/hwd/bre/9/novelist0205.mp3","us":"media/ldoce/hwd/ame/6/novelist.mp3"},"examples":[{"en":"a romantic/historical novelist","cn":"言情/历史小说家"}],"oxford":{"phon":"ˈnɒvəlɪst","pos":"noun","senses":[{"en":"a person who writes novels","cn":"小说家","lab":"US English","ex":{"en":"a romantic/historical novelist","cn":"言情／历史小说家"}}]}},"notoriety":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"声名狼藉;臭名昭著","en":"To achieve notoriety means to become well-known for something bad.","ex":{"en":"He achieved notoriety as chief counsel to President Nixon in the Watergate break-in.","cn":"他因在水门事件中担任尼克松总统的首席法律顾问而声名狼藉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to become well known, especially as a result of hard work or an unusual achievement","cn":""},{"en":"to become famous, especially suddenly","cn":""},{"en":"to become famous for something bad","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Notoriety is fame you get from doing something bad or being part of a misfortune or scandal. Just remember: Notoriety 's not al-righty. Charles Manson earned notoriety for his grisly crimes."}]},"collocations":{"phrases":["ADJ. sudden | certain | international, public","VERB + NOTORIETY have | achieve, gain He achieved sudden notoriety when the details of his private life were revealed. | bring","PREP. ~ for This make of car has a certain notoriety for rust problems."]},"media":{"uk":"media/ldoce/hwd/bre/6/notoriety0205.mp3","us":"media/ldoce/hwd/ame/7/notoriety.mp3"},"examples":[{"en":"She achieved notoriety for her affair with the senator.","cn":"她因为和参议员的风流韵事而声名狼藉。"},{"en":"He gained a certain notoriety as a gambler.","cn":"他落了个赌徒的恶名。"}],"oxford":{"phon":"ˌnəʊtəˈraɪəti","pos":"noun","senses":[{"en":"the state of being famous for being bad in some way","cn":"恶名；坏名声","ex":{"en":"She achieved notoriety for her affair with the senator.","cn":"她因为和参议员私通而声名狼藉。"}}]}},"northwest":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the direction that is exactly between north and west","cn":"西北﹐西北方"},{"en":"the northwestern part of a country 〔","cn":"一国的〕西北部"},{"en":"a northwest wind comes from the northwest 〔","cn":"风〕来自西北的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/northwest_adj0205.mp3","us":"media/ldoce/hwd/ame/0/northwest.mp3"},"examples":[{"en":"the northwest suburbs of the city","cn":"城市西北部的郊区"}]},"notable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"值得注意的;显著的;有趣的","en":"Someone or something that is notable is important or interesting. →see usage note at:","ex":{"en":"The proposed new structure is notable not only for its height, but for its shape","cn":"拟建的新建筑令人瞩目，不仅是因其高度，也因其外形。"}},{"pos":"N-COUNT 可数名词","cn":"显要人物;有势力的人","en":"Notables are important or powerful people.","ex":{"en":"Elected by local notables for nine years Senators lack the democratic legitimacy of members of the National Assembly","cn":"由当地名流选出、任职9年的参议员缺少国民议会议员的民主合法性。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"important, interesting, excellent, or unusual enough to be noticed or mentioned","cn":"显要的﹔显著的﹔值得注意的"},{"en":"notable feature/example A notable feature of the church is its unusual bell tower.","cn":"这座教堂的一个特别之处就是它那座与众不同的钟楼。 notable achievement/success/victory Every country in the world signed the treaty, with one nota"}]},"vocab":{"pos":"adj n","senses":[{"en":"When something is notable , it's worthy of notice , or even famous. It might be a notable feature of your trip to New York City that you spotted one of the city's notable celebrities."}]},"collocations":{"phrases":["VERBS be","ADV. especially, particularly","PREP. for The drawing room is particularly notable for its splendid oak panelling."]},"media":{"uk":"media/ldoce/hwd/bre/f/notable0205.mp3","us":"media/ldoce/hwd/ame/f/notable1.mp3"},"examples":[{"en":"With a few notable exceptions, everyone gave something.","cn":"人人都给了些东西，只有几个人例外，很是显眼。"},{"en":"The town is notable for its ancient harbour.","cn":"这座小镇因其古老的港口而出名。"}],"oxford":{"phon":"ˈnəʊtəbl","pos":"adjective","senses":[{"en":"deserving to be noticed or to receive attention; important","cn":"值得注意的；显著的；重要的","ex":{"en":"a notable success/achievement/example","cn":"显著的成功／成就；明显的事例"}},{"en":"a famous or important person","cn":"名人；重要人物","ex":{"en":"All the usual local notables were there.","cn":"经常露面的当地名流都在那里。"},"pos":"noun"}]}},"noose":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"绳套;套索;活扣","en":"A noose is a circular loop at the end of a piece of rope or wire. A noose is tied with a knot that allows it to be tightened, and it is usually used to trap animals or hang people."},{"pos":"N-COUNT 可数名词","cn":"束缚;圈套;陷阱","en":"You can refer to something that traps people in a difficult situation as a noose around their neck.","ex":{"en":"The rebels are tightening the noose around the capital","cn":"叛乱分子正在收紧对首都的包围。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ring formed by the end of a piece of rope, which closes more tightly as it is pulled, used especially for killing someone by hanging them","cn":"活绳结﹐绳套〔尤指绞索〕"}]},"collocations":{"phrases":["ADJ. hangman's","VERB + NOOSE fasten, tie | pull, tighten | make","NOOSE + VERB tighten","PREP. in/into a/the He put his head into the noose. | ~ around/round They tied a noose round her neck."]},"media":{"img":["media/ldoce/img/noose.jpg"],"uk":"media/ldoce/hwd/bre/4/noose0205.mp3","us":"media/ldoce/hwd/ame/d/noose.mp3"},"examples":[{"en":"( figurative ) His debts were a noose around his neck.","cn":"债务就像套在他脖子上的一条套索。"},{"en":"His debts were a noose around his neck.","cn":""}],"oxford":{"phon":"nuːs","pos":"noun","senses":[{"en":"a circle that is tied in one end of a rope, with a knot that allows the circle to get smaller as the other end of the rope is pulled, that can be used to kill somebody by hanging them by the neck","cn":"绳套；套索；活扣","lab":"figurative","ex":{"en":"a hangman’s noose","cn":"绞索"}}]}},"notify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"通知;告知","en":"If you notify someone of something, you officially inform them about it.","ex":{"en":"The skipper notified the coastguard of the tragedy","cn":"船长向海岸警卫队报告了这起灾难。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to officially tell someone about something","cn":""},{"en":"to tell people publicly and officially about something","cn":""},{"en":"to officially tell someone about something that has happened","cn":""}]},"collocations":{"phrases":["ADV. forthwith, immediately | in advance | by post, in writing | formally","VERB + NOTIFY be obliged to, be required to, must, should If you see anything suspicious you should notify the police immediately. | fail to","PREP. of All applicants will be notified of the result by post. | to Changes must be notified to the chairman."]},"media":{"uk":"media/ldoce/hwd/bre/7/notify0205.mp3","us":"media/ldoce/hwd/ame/d/notify.mp3"},"examples":[{"en":"Members have been notified that there will be a small increase in the fee.","cn":"会员已经得到通知，费用将有小幅上调。"},{"en":"The police must be notified of the date of the demonstration.","cn":"必须向警方报告游行示威的日期。"}],"oxford":{"phon":"ˈnəʊtɪfaɪ","pos":"verb","senses":[{"en":"to formally or officially tell somebody about something","cn":"（正式）通报，通知","ex":{"en":"Competition winners will be notified by post.","cn":"将发信通知竞赛的优胜者。"}}]}},"nominate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(为工作或职位)提名，推荐","en":"If someone is nominated for a job or position, their name is formally suggested as a candidate for it.","ex":{"en":"Under party rules each candidate has to be nominated by 55 Labour MPs","cn":"根据党章，每个候选人必须得到55名工党下院议员的提名。"}},{"pos":"VERB 动词","cn":"任命;指定","en":"If you nominate someone to a job or position, you formally choose them to hold that job or position.","ex":{"en":"Voters will choose fifty of the seventy five deputies. The Emir will nominate the rest","cn":"选民将选出75名代表中的50名，其余代表由埃米尔任命。"}},{"pos":"VERB 动词","cn":"(为某奖项)提名(演员、影片等)","en":"If someone or something such as an actor or a film is nominated for an award, someone formally suggests that they should be given that award.","ex":{"en":"Practically every movie he made was nominated for an Oscar.","cn":"他执导的影片几乎每部都获得过奥斯卡奖提名。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone your ideas about what they should do","cn":""},{"en":"to suggest that someone goes somewhere, tries something etc because you know that it is good and you think they will like it","cn":""},{"en":"to formally suggest a plan or course of action, especially at a meeting","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you suggest a person for a position in the government, or propose a theme for your school's prom, you nominate that person or idea, especially if it's done in an official way."}]},"collocations":{"phrases":["ADV. formally, officially","VERB + NOMINATE ask sb to, invite sb to Ten critics were asked to nominate their Book of the Year.","PREP. as He has now been formally nominated as presidential candidate. | for She was nominated for a special award. | to He has been nominat","PHRASES the power/right to nominate sb"]},"media":{"uk":"media/ldoce/hwd/bre/e/nominate0205.mp3","us":"media/ldoce/hwd/ame/1/nominate.mp3"},"examples":[{"en":"She has been nominated for the presidency.","cn":"她已经获得了董事长职位的提名。"},{"en":"He was nominated (as) best actor.","cn":"他获得了最佳男演员的提名。"}],"oxford":{"phon":"ˈnɒmɪneɪt","pos":"verb","senses":[{"en":"to formally suggest that somebody/something should be chosen for an important role, prize, position, etc.","cn":"提名；推荐","ex":{"en":"She has been nominated for the presidency.","cn":"她已经获得了董事长职位的提名。"}},{"en":"to choose somebody to do a particular job","cn":"任命；指派","ex":{"en":"I have been nominated to the committee.","cn":"我被任命为委员会委员。"}},{"en":"to choose a time, date or title for something","cn":"挑选，指定（时间、日期、名称等）","ex":{"en":"1 December has been nominated as the day of the election.","cn":"12 月 1 日被指定为选举日。"}}]}},"nostril":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鼻孔","en":"Your nostrils are the two openings at the end of your nose."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two holes at the end of your nose, through which you breathe and smell things","cn":"鼻孔"}]},"collocations":{"phrases":["VERB + NOSTRIL clog, fill The stench of the cellar filled my nostrils.","NOSTRIL + VERB dilate, flare","NOSTRIL + NOUN hair","PREP. in your ~s The smell of decay lingered in her nostrils. | through your ~s She drew on the cigarette and blew smoke through her nostril"]},"media":{"uk":"media/ldoce/hwd/bre/e/nostril0205.mp3","us":"media/ldoce/hwd/ame/b/nostril.mp3"},"examples":[{"en":"The smell of gunpowder filled his nostrils.","cn":"火药味灌进他的鼻孔。"},{"en":"the horse’s flaring nostrils (= widened nostrils )","cn":"马儿张大的鼻孔"}],"oxford":{"phon":"ˈnɒstrəl","pos":"noun","senses":[{"en":"either of the two openings at the end of the nose that you breathe through","cn":"鼻孔","ex":{"en":"The horse flared its nostrils.","cn":"马张开鼻孔。"}}]}},"north-eastern":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(在)东北部的;来自东北部的","en":"North-eastern means in or from the north-east of a region or country.","ex":{"en":"...the north-eastern coast of the United States.","cn":"美国东北部海岸"}}]},"oxford":{"phon":"ˌnɔːθ ˈiːstən","pos":"adjective","senses":[{"en":"connected with the north-east","cn":"东北的；东北方向的"}]}}});
